import type { ArticleCore } from "../types";

export const CORES_B: Record<string, ArticleCore> = {
  mathematics: {
    lede: `Mathematics is the study of structure made exact: number, space, change, chance, and the relations that remain when names are stripped away. It occupies a continent of the [[knowledge-atlas|Knowledge Atlas]], bordering [[physics|physics]], [[computing|computing]], and [[philosophy|philosophy]] along seams of [[logic|logic]] and [[proof|proof]]. From [[euclid|Euclid]]'s Elements around 300 BCE to [[godel|Gödel]]'s incompleteness theorems of 1931, its public method has been the conversion of private insight into shared certainty. Interior ranges include [[number-theory|number theory]], [[calculus|calculus]], [[linear-algebra|linear algebra]], [[topology|topology]], [[probability|probability]], and [[graph-theory|graph theory]]. The field invents worlds, then asks which of them can be inhabited by a theorem.`,
    idea: `A mathematical object is not a thing in the world so much as a license to compute, classify, and compare. Integers and [[prime-numbers|prime numbers]] give [[number-theory|number theory]] its atoms; vector spaces give [[linear-algebra|linear algebra]] a geometry of maps; open sets give [[topology|topology]] a notion of nearness without a ruler. [[calculus|Calculus]] treats change as a limit; [[probability|probability]] treats uncertainty as a measure; [[graph-theory|graph theory]] treats relation as an edge. These are not metaphors stacked on experience. They are machines that survive translation into [[physics|physics]], into [[algorithms|algorithms]], into the architecture of [[machine-learning|machine learning]]. The atlas keeps the field as a hub because the other continents borrow its dialect whenever they need a claim to outlive a laboratory. What looks from a course catalog like a sequence of techniques is, up close, a federation of temperaments held together by [[proof|proof]] and by a taste for [[infinity|infinity]]. Hilbert's twenty-three problems of 1900 still mark which rooms of this house remain unfinished, from the arithmetic of elliptic curves to the continuum of [[infinity|infinity]].`,
    lineage: `Clay tablets from Old Babylon already list Pythagorean triples; the Nine Chapters on the Mathematical Art, compiled in Han China, teaches Gaussian elimination without Gauss. [[euclid|Euclid]] made the axiomatic walk canonical. [[euler|Euler]] in the eighteenth century treated analysis, number, and [[networks|networks]] as one workshop. [[gauss|Gauss]] and [[riemann|Riemann]] bent geometry until [[einstein|Einstein]] could put gravity into it. The nineteenth century arithmetized the continuum and invented [[set-theory|set theory]]; the twentieth asked, with Hilbert and then [[godel|Gödel]], how much of that edifice could be captured by a formal system. Bourbaki tried to rewrite the continent as a single structure. Category theorists proposed arrows instead of elements. Computers began to check, and sometimes to find, proofs. The lineage is not a ladder. It is a braided river whose channels rejoin whenever someone needs a new kind of [[infinity|infinity]] or a new standard of [[proof|proof]].`,
    tension: `The oldest quarrel is whether mathematics is discovered or made — Plato's heaven against the workshop. A newer quarrel is whether a [[proof|proof]] that no human can survey, such as the 1976 four-color argument or a massive formalization in Lean, still counts as understanding. [[godel|Gödel]] showed that any sufficiently rich axiomatic system leaves truths it cannot certify; independence results about the continuum leave [[set-theory|set theory]] with several possible infinities. Applications in [[cryptography|cryptography]] and [[machine-learning|machine learning]] pull the field toward use, while [[category-theory|category theory]] pulls it toward a language about languages. The atlas does not pick a winner. It keeps the fault visible: a continent that claims certainty is also a continent that cannot, from inside, prove that its foundations are the only ones.`,
  },

  "number-theory": {
    lede: `Number theory is the higher arithmetic: the study of integers, congruences, Diophantine equations, and the secret regularities of [[prime-numbers|prime numbers]]. Gauss called it the queen of [[mathematics|mathematics]] in the Disquisitiones Arithmeticae of 1801, and the epithet has stuck because elementary questions — which numbers are sums of two squares, which equations have integer solutions — hide machinery of startling depth. The field talks to [[cryptography|cryptography]] whenever a trapdoor is needed, and to [[proof|proof]] whenever a conjecture has sat for centuries. [[riemann|Riemann]]'s zeta function moved primes into analysis; [[euler|Euler]]'s product formula had already shown that primes know about the harmonic series.`,
    idea: `At the center sit the integers and the primes that generate them under multiplication. Euclid proved there are infinitely many primes; the fundamental theorem of arithmetic says the factorization is unique. Modular arithmetic, systematized by [[gauss|Gauss]], treats remainders as a world of their own, the setting for Euler's totient function and for the Chinese remainder theorem. Analytic number theory estimates how primes thin out: the prime-number theorem, proved independently by Hadamard and de la Vallée Poussin in 1896, says that around x the density is about 1/ln x. Algebraic number theory enlarges the integers to rings of algebraic integers, where unique factorization can fail and ideals repair the damage. L-functions package this arithmetic into complex analysis. Wiles's 1995 proof of Fermat's Last Theorem, via modularity of semistable elliptic curves, showed how a folk riddle can force an entire architecture into existence. The field's working objects — modular forms, Galois representations, schemes — are far from pebbles, yet they answer questions a child can ask.`,
    lineage: `Diophantus of Alexandria posed equations in integers; Fermat read him in the seventeenth century and scattered challenges, including the margin note that became Fermat's Last Theorem. [[euler|Euler]] proved cases, invented the zeta function for integers, and linked primes to infinite products. [[gauss|Gauss]] recast quadratic reciprocity and cyclotomy as a finished art. Dirichlet introduced L-functions to prove infinitely many primes in arithmetic progressions. [[riemann|Riemann]] in 1859 suggested that the zeros of zeta govern the error in counting primes. Hilbert's twelfth problem, class field theory, and the Langlands program of the late 1960s recast number theory as a web of correspondences between analysis and Galois groups. Computational practice — from Gauss's hand calculations to the AKS primality test of 2002 — kept the integers tactile even as the language grew sheaf-theoretic. The Birch–Swinnerton-Dyer conjecture, a Clay problem like Riemann's, still asks how the rank of an elliptic curve hides in an L-function's zero.`,
    tension: `The Riemann hypothesis remains the outstanding bet of the field: that the nontrivial zeros of zeta lie on the critical line Re(s) = 1/2. A proof would pin down the error term in the prime-number theorem; a counterexample would scramble a century of heuristics. Meanwhile [[cryptography|cryptography]] lives on the assumption that factoring and discrete logarithms are hard, an empirical claim number theory has not proved and quantum algorithms threaten. Effective results often lag existence proofs: we know primes exist in strange sequences before we can exhibit them. The tension is not that the integers are mysterious. It is that their mysteries now sit at the junction of [[proof|proof]], computation, and the physical limits of [[computing|computing]].`,
  },

  calculus: {
    lede: `Calculus is the mathematics of continuous change: derivatives that capture rates, integrals that accumulate, and limits that make both precise. Invented twice in the late seventeenth century, by Isaac Newton for [[physics|physics]] and by Gottfried Wilhelm Leibniz for a notation the world kept, it became the dialect of motion, growth, and field. Berkeley mocked its vanishing increments in The Analyst of 1734; Cauchy and Weierstrass answered by rebuilding it on epsilon and delta. The topic now shades into real and complex analysis, into [[fourier-analysis|Fourier analysis]], and into the stochastic calculus that [[probability|probability]] uses to price risk and model noise.`,
    idea: `The derivative of a function at a point is the best linear approximation there; the definite integral is a signed accumulation of values. The fundamental theorem of calculus, in the form made standard after Newton and Leibniz, says these operations invert one another under mild hypotheses. Partial derivatives and multiple integrals extend the story to several variables; Stokes's theorem and its kin (Green, Gauss, Cartan) unify the vector calculus that electricity and fluid flow actually use. Ordinary differential equations describe clocks, circuits, and populations; partial differential equations describe heat, waves, and spacetime curvature. Existence, uniqueness, and stability are the analytic questions; explicit closed forms are the rare prize. Numerical analysis, from Euler steps to finite elements, is how most of the world computes a derivative it cannot write. The subject is less a single trick than a stance: treat the continuous as limit of the discrete, then recover theorems that the discrete only suggested.`,
    lineage: `Archimedes' method of exhaustion computed areas by squeezing; Indian and Islamic mathematicians, notably Madhava of the Kerala school, found series for sine and pi centuries before Europe. Newton, in the 1660s, used fluxions to solve orbital problems; Leibniz, in the 1670s, published dx and the elongated S of the integral. The Bernoulli brothers, [[euler|Euler]], and Lagrange built a calculus of variations and of infinite series. Fourier claimed, in 1822, that arbitrary functions were sums of sines; Dirichlet and Riemann asked when that was true. Cauchy's Cours d'analyse of 1821 and Weierstrass's lectures expelled intuition's ghosts. Lebesgue's 1902 integral enlarged the class of integrable functions; Schwartz's distributions let physicists differentiate step functions in good conscience. Nonstandard analysis, in Abraham Robinson's hands, even restored infinitesimals as honest numbers. Arnold later taught that the same calculus of variations organizes optics, mechanics, and the geometry of symplectic manifolds.`,
    tension: `Rigor and use do not keep the same clock. Engineers ship products on formalisms analysts still fence with counterexamples; physicists differentiate under integral signs that theorems only later bless. The continuum itself is philosophically loaded: is it a completed [[infinity|infinity]] of points, a potential process, or a computational approximation? Constructive and computable analysis refuse some classical existence proofs. [[chaos-theory|Chaos theory]] showed that perfectly deterministic equations can be unpredictably sensitive, so the calculus of the solar system does not yield the calculus of next month's weather. The open problem is not whether change can be mathematized. It is how much of a messy world a limit can be forced to confess.`,
  },

  "linear-algebra": {
    lede: `Linear algebra is the geometry of linear maps: vector spaces, matrices, eigenvalues, and the art of changing coordinates until a problem looks like stretching along axes. It is the skeleton inside quantum theory, inside computer graphics, and inside [[machine-learning|machine learning]], where a neural net is a cascade of linear transforms interrupted by simple nonlinearities. Gaussian elimination is older than [[gauss|Gauss]]; the Nine Chapters already reduce systems of linear equations. Cayley named matrices in 1858; Grassmann's Ausdehnungslehre of 1844 imagined spaces of arbitrary dimension before anyone needed them.`,
    idea: `A vector space is a set closed under addition and scaling; a linear map sends sums to sums and stretches uniformly. Choose bases and the map becomes a matrix, a rectangular array that can be multiplied, inverted when possible, and decomposed. Rank measures dimension of the image; nullity, of the kernel; the rank-nullity theorem balances them. Eigenvectors are directions a map merely scales; diagonalization, when it works, is the dream of seeing a map as independent stretches. When it fails, Jordan form or singular-value decomposition still extract a canonical picture. Inner products add angles and lengths, turning algebra into Euclidean geometry and, in infinite dimensions, into Hilbert space. Least squares, principal components, and the Fourier transform are all, in this light, projections. The subject's power is ruthlessly practical: once a phenomenon is approximately linear, the whole toolkit — invert, factor, spectrally decompose — applies without asking what the coordinates meant.`,
    lineage: `Babylonian tablets solve two-by-two systems; Liu Hui's commentary on the Nine Chapters describes elimination with counting rods. Leibniz hinted at determinants; Cramer gave a formula; Vandermonde and Cauchy sharpened them. Hamilton's quaternions and Grassmann's extensive quantities opened higher dimensions as algebraic objects. Sylvester and Cayley treated matrices as things, not mere bookkeeping. The spectral theorem for symmetric matrices grew through Cauchy, Weierstrass, and Hilbert, who then took it into infinite dimensions for integral equations. Von Neumann used Hilbert space as the stage for quantum mechanics. Householder, Wilkinson, and Golub made numerical linear algebra a discipline of stability, condition numbers, and floating-point honor. In the late twentieth century, sparse matrices and randomized algorithms scaled the subject to the web and to genomic tables. Strassen's 1969 matrix multiplication, and later Coppersmith–Winograd improvements, showed that even multiplication is an [[algorithms|algorithms]] problem, not a closed chapter of the subject.`,
    tension: `Linearity is a brilliant lie about a nonlinear world. The tension is when to trust the approximation: near equilibrium it is gospel; far away it is a first sentence. High dimension brings its own pathologies — concentration of measure, the curse of dimensionality — so that intuition trained in R^3 betrays you in R^n. Numerical reality adds another fault line: theoretically invertible matrices become computationally singular, and [[algorithms|algorithms]] must report not an inverse but a warning. In [[machine-learning|machine learning]], overparameterized linear-ish models interpolate noise yet sometimes generalize, a fact theory still chases. Linear algebra is finished as an undergraduate chapter and unfinished as a living method, which is a polite way of saying the skeleton keeps growing new bones.`,
  },

  topology: {
    lede: `Topology is geometry without a ruler: the study of properties that survive stretching, bending, and continuous deformation, but not tearing. A coffee cup is a doughnut because each has one hole; a sphere is not. [[euler|Euler]]'s formula V − E + F = 2 for convex polyhedra, from 1750, is an ancestor; Johann Listing coined Topologie in 1847; Poincaré's Analysis Situs of 1895 made algebraic invariants a program. The field classifies spaces by homotopy and homology, asks when maps can be deformed into one another, and supplies the language in which [[riemann|Riemann]]'s manifolds and, later, [[einstein|Einstein]]'s spacetime were made precise.`,
    idea: `An open set is the primitive: a topology on a space is a collection of opens closed under unions and finite intersections. Continuity becomes the statement that preimages of opens are open, with no epsilons required. Compactness, connectedness, and Hausdorff separation are the adjectives that make spaces behave. Algebraic topology assigns to each space algebraic objects — homotopy groups, homology groups, cohomology rings — so that continuous questions become calculable. Brouwer's fixed-point theorem says a continuous self-map of a disk has a still point; it is why stirring coffee leaves a particle unmoved, and why some economic equilibria exist. Differential topology studies smooth manifolds and cobordism; geometric topology studies knots, 3-manifolds, and the Poincaré conjecture, settled by Perelman in 2003 using Ricci flow. The working idea is classification by invariant: find a quantity unchanged by deformation, compute it, and know which spaces cannot be the same. Poincaré duality, cobordism rings, and the classification of surfaces (sphere, torus, and higher genus) are the first complete successes of that program, against which harder dimensions are judged.`,
    lineage: `Descartes and [[euler|Euler]] counted faces of polyhedra; Möbius and Listing described one-sided surfaces in the 1850s. Riemann treated multiply connected domains as essential to complex analysis. Poincaré introduced fundamental groups and homology, then left conjectures that organized a century. Brouwer made dimension and fixed points rigorous and, as an intuitionist, distrusted some of the infinities he used. Lefschetz, Hopf, and Whitney built intersection theory and vector bundles. Eilenberg and Steenrod axiomatized homology; Cartan and Eilenberg, then Grothendieck, moved the algebra into abelian categories and sheaves. Thurston conjectured a geometrization of 3-manifolds; Hamilton proposed Ricci flow; Perelman finished both and declined the Fields Medal. Persistent homology now takes the subject into data, hunting shape in point clouds. Fox, Seifert, and later Thurston made knot theory a laboratory; Freedman's work on 4-manifolds showed that topology in four dimensions is a world apart from the smooth one.`,
    tension: `Point-set topology can be made so general that almost no theorem survives; the tension is how much separation and countability to demand before the word space still means something a geometer would recognize. Algebraic invariants are complete only in dreams: homotopy groups of spheres remain a wilderness, and most manifolds are not classified. Computer-assisted and gauge-theoretic methods (Donaldson, Freedman, Witten) split 4-manifold theory into smooth and topological worlds that disagree. Applied topology, in data analysis and in [[networks|networks]], borrows the words without always inheriting the theorems. The open problem is not a shortage of definitions. It is that the classification program, once you leave low dimensions, is genuinely incomplete, and [[infinity|infinity]] of possible spaces is not a figure of speech.`,
  },

  probability: {
    lede: `Probability is the mathematics of uncertainty: a number between zero and one assigned to events, then manipulated until inference, prediction, and risk become calculable. It began with dice and correspondence — Pascal and Fermat in 1654 settling a gambler's quarrel — and became, in Kolmogorov's Grundbegriffe of 1933, a chapter of measure theory. The topic now runs from card shuffling to the Bayesian brain, from statistical mechanics to the stochastic calculus of finance. It neighbors [[information-theory|information theory]] and [[entropy|entropy]], because surprise has a size; it neighbors [[calculus|calculus]], because continuous chance needs integrals.`,
    idea: `A probability space is a set of outcomes, a sigma-algebra of events, and a countably additive measure normalized to one. Random variables are measurable functions; expectation is integration; independence is a product condition that makes joint distributions factor. Conditional probability, via Bayes's theorem, is the update rule: prior times likelihood, renormalized, yields posterior. The law of large numbers explains why frequencies settle; the central limit theorem, glimpsed by de Moivre and proved in expanding generality through Lyapunov and Lindeberg, explains why noise so often looks Gaussian. Markov chains forget their past at a controlled rate; martingales are fair games, the backbone of modern stochastic processes. Measure-theoretic rigor lets one handle uncountable outcome spaces without paradox, while still recovering the finite counting of combinatorics as a special case. The working idea is that chance is not the opposite of structure. It is a structure — a measure — and therefore a thing theorems can pin.`,
    lineage: `Cardano wrote on games in the sixteenth century; Huygens's De ratiociniis in ludo aleae of 1657 was the first printed treatise. Jacob Bernoulli's Ars Conjectandi, posthumous in 1713, proved a law of large numbers and introduced the binomial named for him. De Moivre approximated binomials by the normal curve; Bayes's essay of 1763, published after his death by Price, gave the inversion that still divides schools. Laplace's Théorie analytique des probabilités of 1812 made the subject a planetary tool. Quetelet brought the average man; Maxwell and Boltzmann brought ensembles of particles. Borel, Lebesgue, and Fréchet supplied measure; Kolmogorov in 1933 wrote the axioms that ended the foundational brawl without ending interpretation. Kac, Doob, Itô, and Lévy built processes; Shannon, in 1948, made uncertainty a bit. Feller's two volumes taught a generation the subject as a branch of [[mathematics|mathematics]] rather than a bag of tricks, and Itô's integral made Brownian motion a tool of [[physics|physics]] and finance alike.`,
    tension: `The same axioms admit several philosophies. Frequentists read probability as long-run frequency; Bayesians as degree of belief; propensity theorists as a disposition of the experimental setup. In quantum theory the Born rule adds a further reading that still splits physicists. Paradoxes of infinity — Bertrand's chord, nonmeasurable sets if one assumes choice — show that intuition about "at random" is not a definition. Tail events and black swans mock models that treat independent Gaussians as the world's weather. [[entropy|Entropy]] and [[information-theory|information theory]] pull probability toward coding and physics; machine statisticians pull it toward prediction without interpretation. The open problem is not computational. It is what the number is when the experiment cannot be repeated, and who is allowed to change it when evidence arrives.`,
  },

  "graph-theory": {
    lede: `Graph theory is the mathematics of connection: vertices joined by edges, directed or not, weighted or not, and the shapes of relation that result. [[euler|Euler]] founded it in 1736 by showing that the seven bridges of Königsberg cannot be traversed each once and returned, because the city's graph had too many odd-degree vertices. The topic now underwrites [[networks|networks]], [[algorithms|algorithms]], and the [[knowledge-atlas|Knowledge Atlas]] itself, which is a graph of ideas wearing the costume of an encyclopedia. Four colors suffice for planar maps, as Appel and Haken demonstrated in 1976 with machine assistance; Ramsey theory asks how large a system must be before a given substructure is forced.`,
    idea: `A graph is a pair of sets, vertices and edges, sometimes with loops, multiples, or directions. Degree, path, cycle, tree, and matching are the basic vocabulary; connectivity asks how many vertices or edges must be deleted to disconnect the rest. Eulerian circuits traverse every edge; Hamiltonian cycles visit every vertex, a problem that is NP-complete and therefore a landmark of computational hardness. Planarity, Kuratowski's forbidden minors, and Euler's formula V − E + F = 2 (for connected plane graphs) tie the subject to topology. Spectral graph theory reads adjacency and Laplacian matrices until expansion, coloring, and random walks become eigenvalues. Random graphs, in the Erdős–Rényi model of 1959, undergo sudden transitions: a giant component appears as if a switch were thrown. The working idea is that relation has a shape, and that shape can be counted, optimized, and sometimes drawn without crossings. Flows and cuts, in the max-flow min-cut theorem of Ford and Fulkerson, turn a picture of pipes into a duality; coloring, matching, and expansion are the other classical engines.`,
    lineage: `After Königsberg, Kirchhoff analyzed electrical circuits as graphs in 1847; Cayley enumerated trees, including chemical isomers. The four-color conjecture, posed by Guthrie in 1852 and popularized by De Morgan and Cayley, organized chromatic graph theory for more than a century. König, Petersen, and Menger developed matchings and connectivity. Ramsey's 1930 theorem, and Erdős's probabilistic method, created an extremal culture: how much can you have before a pattern is inevitable. Tutte characterized regular matroids; Robertson and Seymour, across a vast series of papers, proved the graph-minor theorem. Computers entered as colleagues: Appel and Haken's four-color proof, and later formalizations, made surveyability a philosophical issue. The internet, citation webs, and biological interaction maps then demanded a statistical physics of graphs, scale-free and otherwise. Lovász, Szemerédi, and the Hungarian school made extremal graph theory a precision instrument; the graph-minor theorem of Robertson and Seymour occupies a unique place in the history of long [[proof|proof]].`,
    tension: `Drawing a graph is not understanding it; most graphs of interest are too large to see, and visualization becomes a rhetoric. The P-versus-NP question sits inside the subject like a trapped nerve: Hamiltonian cycles, cliques, and colorings are easy to state and, so far as anyone knows, hard in general. Applied network science sometimes treats power-law degrees as destiny, then discovers sampling artifacts. Discrete and continuous imaginations quarrel at the boundary with [[topology|topology]] and with geometric group theory. Another tension is ethical rather than formal: the same [[algorithms|algorithms]] that find communities in a graph of ideas can partition people. Graph theory does not choose its applications. It only guarantees that connection, once defined, will have consequences.`,
  },

  euclid: {
    lede: `Euclid of Alexandria, flourishing around 300 BCE, wrote the Elements, thirteen books that taught the West what a [[proof|proof]] looks like: definitions, common notions, postulates, then theorems that follow. Almost nothing certain is known of his life; the work is the biography. For two millennia geometry meant Euclid, and [[mathematics|mathematics]] meant the Euclidean standard of rigor even when the content was number or astronomy. The parallel postulate, innocent on the page, became the fault line from which non-Euclidean geometries erupted in the nineteenth century. He is filed here as a person so that axiomatic method has a face, not because the face can be recovered from the text.`,
    idea: `The Elements is a machine for making agreement. Book I builds triangles and parallels; Book II treats geometric algebra; Books VII–IX are number theory, including the infinitude of [[prime-numbers|prime numbers]] and the Euclidean algorithm for greatest common divisors. Book X classifies irrationals with a patience that still startles; Books XI–XIII erect solid geometry and the five Platonic solids. The method is synthetic: each proposition cites earlier ones, so that a reader who grants the postulates is, in principle, trapped into the pyramid's volume. Euclid also wrote on optics, astronomy (the Phaenomena), and division of figures; the Data studies what is determined when what is given. The parallel postulate — that through a point not on a line there is exactly one parallel — was long suspected of being a theorem. It was not. Its independence, shown by consistent models of hyperbolic geometry, is among the great negative results of [[mathematics|mathematics]], and it begins in Euclid's list.`,
    lineage: `He worked in Ptolemaic Alexandria, heir to Plato's Academy and to Eudoxus's theory of proportion, which Book V preserves. Proclus, in the fifth century CE, is the main biographical source and already a commentator rather than a witness. Islamic mathematicians, notably Omar Khayyam and Nasir al-Din al-Tusi, probed the parallel postulate with alternative constructions. Medieval Europe received Euclid through Boethius, then through Arabic-Latin translations; the first printed edition appeared in Venice in 1482. Commandino, Clavius, and later Playfair recast the postulates for classrooms. Hilbert's Grundlagen der Geometrie of 1899 re-axiomatized the subject, filling gaps (betweenness, continuity) that Euclid's diagrams had silently plugged. In that sense Euclid's afterlife is the history of noticing what he had not said. Heiberg's edition of the Greek text, and Heath's 1908 English, remain the scholar's doors; school editions quietly skip the exhaustion proofs that once trained a reader in [[infinity|infinity]] as method.`,
    tension: `Was Euclid a compiler or an architect? Scholarship still divides. The Elements may package earlier Pythagorean and Eudoxan work; originality and arrangement then come apart. A second tension is pedagogical: generations learned [[proof|proof]] as imitation of Euclid, then met a nineteenth-century rigor that found him full of hidden appeals to diagrams. Non-Euclidean geometry did not refute him; it showed that his fifth postulate was a choice, and that [[philosophy|rationalism]]'s favorite book contained an empirical-looking fork. He remains the emblem of certainty in [[mathematics|mathematics]] and the reminder that certainty is relative to axioms one might have refused. A further quarrel is whether diagrams in the Elements are dispensable decoration or part of the warrant: Manders and others have argued that the figure does logical work Euclid's words omit, a claim that unsettles any purely syntactic picture of [[proof|proof]].`,
  },

  gauss: {
    lede: `Carl Friedrich Gauss (1777–1855), the prince of mathematicians, left fingerprints on [[number-theory|number theory]], statistics, differential geometry, and terrestrial magnetism. Born in Brunswick, a prodigy whose addition of 1 to 100 is legend if not fact, he published slowly and stored more in diaries than in journals. The Disquisitiones Arithmeticae of 1801 recast the integers as a finished art; the 1801 recovery of Ceres showed that the same mind could catch a planet. He is a node because later fields still argue in his vocabulary: Gaussian integers, Gaussian curvature, Gaussian elimination, the Gaussian distribution that [[probability|probability]] cannot do without.`,
    idea: `The Disquisitiones introduced modular arithmetic as a language, proved quadratic reciprocity (his theorema aureum, eventually given six proofs by his own hand), and developed cyclotomy until the constructibility of the regular 17-gon fell out. In astronomy and geodesy he refined least squares, a method Legendre had published and Gauss claimed to have used since 1795; the quarrel is still a footnote with teeth. Differential geometry, in the Disquisitiones generales circa superficies curvas of 1828, produced Gaussian curvature and the theorema egregium: curvature is intrinsic, independent of how a surface sits in space. With Wilhelm Weber he built a magnetic observatory and a primitive telegraph; the Gauss as a unit of magnetic induction is a later honorific. He treated complex numbers as a plane, proved the fundamental theorem of algebra more than once, and left unpublished notes on non-Euclidean geometry that might have made him, rather than Bolyai and Lobachevsky, its public founder.`,
    lineage: `A ducal scholarship sent him to Göttingen. His teacher was Kästner; his true interlocutors were the integers and, later, [[riemann|Riemann]], who as a student in 1854 lectured on the hypotheses of geometry while Gauss, aging, listened with rare praise. He corresponded with Bessel, Olbers, and Sophie Germain (at first under her male pseudonym). Napoleonic Europe, the duchy of Brunswick, and the kingdom of Hanover were the political weather; he stayed, calculated, and declined invitations that would have made him a Parisian. After his death, editors spent decades extracting from papers what he had not bothered to print. The diary, discovered later, showed how often he had been first. The Ceres orbit, computed in 1801 from Piazzi's scant observations by least squares and the method of normal equations, made him famous beyond [[mathematics|mathematics]] and funded the Hanover triangulation that fed the curvature theorems.`,
    tension: `Gauss's slowness to publish is an ethical problem disguised as a personality: János Bolyai's non-Euclidean geometry met a letter claiming Gauss had known it for decades, a kindness that felt like theft. Priority disputes with Legendre over least squares, and a frostiness toward younger talent, complicate the monument. Mathematically, his conservatism — distrust of [[infinity|infinity]] as Cauchy would later rigorize it, reluctance to print what lacked complete polish — meant that nineteenth-century analysis sometimes had to rediscover him. The afterlife is nevertheless saturating: whenever a bell curve is drawn, a curvature computed, or a congruence written with three bars, his name is the air the calculation breathes. Historians still sift the diary against the printed record to decide when he knew what, a cottage industry that says as much about our hunger for genius as about [[number-theory|number theory]].`,
  },

  godel: {
    lede: `Kurt Gödel (1906–1978) proved that any sufficiently rich consistent formal system cannot prove all the arithmetic truths it can state, nor prove its own consistency. The incompleteness theorems of 1931 ended Hilbert's program as Hilbert had framed it and relocated the philosophy of [[mathematics|mathematics]] around a limit. Born in Brünn (Brno), trained in Vienna among the positivists he did not join, he later walked with [[einstein|Einstein]] at Princeton. He is filed beside [[logic|logic]], [[set-theory|set theory]], [[proof|proof]], and [[infinity|infinity]] because those nodes still take their shape from his results. Turing's machines, and the undecidability of the halting problem, are the computational twin of the same limit.`,
    idea: `Gödel numbering codes symbols, formulas, and proofs as integers, so that a formal system capable of arithmetic can talk, unwittingly, about its own syntax. The first incompleteness theorem constructs a sentence that says, in effect, "I am not provable here"; if the system is consistent, the sentence is true and unprovable. The second shows that such a system cannot prove the arithmetic statement that encodes its consistency, unless it is inconsistent. Completeness, by contrast, he had already proved in 1929 for first-order [[logic|logic]]: every valid first-order sentence has a proof. In [[set-theory|set theory]] he introduced the constructible universe L and showed that if ZF is consistent, so is ZF plus the axiom of choice and the continuum hypothesis. Cohen later showed that the continuum hypothesis can also fail. Gödel's Platonism — the conviction that sets and numbers are as objective as mountains — was not a decoration on the theorems. It was, for him, why the theorems were about something.`,
    lineage: `The First World War, the Austrian republic, and the Vienna Circle were the backdrop; Carnap was a teacher, Hahn a doctoral advisor, and Wittgenstein a near-miss. The 1931 paper appeared in the Monatshefte für Mathematik. After the Anschluss he fled, via the Trans-Siberian Railway, to the Institute for Advanced Study, where he became a colleague of [[einstein|Einstein]] and a recluse of increasing severity. He contributed to relativistic cosmology (rotating universes with closed timelike curves) and to the logic of provability. Late in life he attempted an ontological proof of God in a modal logic, a document published only after his death. He starved himself in 1978, fearing poison. The work did not starve with him. The Gibbs lecture of 1951 stated his Platonism in public: mathematical objects are as objective as physical ones, a stance that put him nearer [[kant|Kant]] and Leibniz than to the Vienna Circle that had housed him.`,
    tension: `Incompleteness is routinely inflated into a sermon against reason; Gödel proved a theorem about formal systems, not a license for mysticism. A live debate is how much of ordinary [[mathematics|mathematics]] lives beyond Peano arithmetic: most analysis can be coded in surprisingly weak systems, so the incompleteness that matters day to day may be rarer than the slogan. Another tension is political-philosophical: his Leibnizian metaphysics and distrust of positivism sat awkwardly in the century that used his result as a weapon against formalism. In [[computing|computing]], incompleteness becomes undecidability, and [[turing|Turing]]'s limit is the engineer's version of Gödel's. The afterlife is a caution: certainty has a radius, and the radius is itself a theorem.`,
  },

  riemann: {
    lede: `Bernhard Riemann (1826–1866) rebuilt geometry as the study of metric manifolds and rebuilt [[number-theory|number theory]] as the study of a complex function's zeros. In an 1854 Habilitationsvortrag at Göttingen, with [[gauss|Gauss]] in the audience, he described spaces of arbitrary dimension whose curvature can vary from point to point — the language [[einstein|Einstein]] would need for gravity. In an 1859 paper on the prime-counting function he introduced the zeta function as a meromorphic object and conjectured that its nontrivial zeros lie on the critical line. He died of tuberculosis at thirty-nine, in Selasca, leaving a handful of papers that fields are still unpacking.`,
    idea: `Riemannian geometry starts with a metric tensor, a smoothly varying inner product on tangent spaces, and derives geodesics, curvature, and volume from it. Gauss had shown curvature to be intrinsic in two dimensions; Riemann took the idea into n dimensions and allowed the metric to be an independent given, not a relic of embedding in Euclidean space. In complex analysis he introduced Riemann surfaces, making multi-valued functions such as the square root into single-valued maps on branched covers, and proved a mapping theorem that identifies simply connected domains. The Riemann–Roch theorem counts independent meromorphic functions on a surface in terms of topology and divisor degree. The 1859 zeta paper is eight pages: analytic continuation, a functional equation, an explicit formula relating primes to zeros, and a hypothesis still open. Few mathematicians have spent so little paper to so much effect. The Dirichlet principle, which he used to construct harmonic functions on surfaces, was later repaired by Hilbert; the gap and its fix became a parable of nineteenth-century rigor meeting geometric imagination.`,
    lineage: `He was born in Breselenz, a pastor's son, and studied in Göttingen and Berlin under Gauss, Steiner, Jacobi, and Dirichlet, whom he succeeded. Poverty, shyness, and the 1848 revolutions framed a short career. Dedekind, his friend, edited the Nachlass and rescued the geometry lecture from obscurity. Beltrami, Christoffel, and Ricci built the tensor calculus; Levi-Civita added parallel transport; Hilbert and Einstein, in 1915, put the machinery into field equations. On the arithmetic side, Hadamard and de la Vallée Poussin proved the prime-number theorem in 1896 without settling the zeros; Hardy showed infinitely many zeros on the line; Selberg and Erdős found elementary proofs of the prime theorem; computers have checked billions of zeros and found no rebel. The hypothesis remains. Weyl's Raum, Zeit, Materie carried Riemannian geometry into the physics of the 1920s; Siegel, Selberg, and Weil rebuilt the arithmetic side as a theory of automorphic forms still unfinished.`,
    tension: `Riemann's papers are sketches by later standards: existence proofs that Weierstrass found wanting, geometric claims that needed a century of tensor analysis to become calculations. The zeta hypothesis is the emblematic open problem of [[mathematics|mathematics]], with a million-dollar Clay reward that has not made it easier. A philosophical tension is whether his manifolds were discovered as the true form of space or invented as a language later physics happened to need; [[einstein|Einstein]]'s success tempts the first reading, the existence of other geometries the second. He left no school in the organizational sense. He left a style: short papers that force later generations to become their own commentators. A further strain is pedagogical: students meet the zeta function as a pretty Euler product long before they can state a single theorem Riemann actually proved about it, so celebrity outruns the papers.`,
  },

  euler: {
    lede: `Leonhard Euler (1707–1783) was the most prolific mathematician who has ever lived, a writer of some 800 papers and books who treated analysis, number, mechanics, and [[graph-theory|graph theory]] as one workshop. Born in Basel, a student of Johann Bernoulli, he worked in St. Petersburg and Berlin, remaining productive after blindness. Euler's identity e^{iπ} + 1 = 0 is the celebrity; the Euler characteristic, the totient function, and the Königsberg argument of 1736 are the infrastructure. He is a node of [[calculus|calculus]], [[number-theory|number theory]], and [[networks|networks]] because those fields still speak sentences he wrote first. Where [[gauss|Gauss]] withheld, Euler published, and the continent grew by the acre.`,
    idea: `Euler made analysis a toolkit rather than a collection of tours de force. He treated infinite series and products as objects one could manipulate, often formally, and extracted closed forms — the Basel problem, ζ(2) = π²/6, solved in 1734 — that justified the daring. He introduced the notation f(x), e for the base of natural logarithms, i for the imaginary unit, and Σ for sums; the symbols are so familiar they no longer look like inventions. In number theory he proved Fermat's little theorem in modern form, studied partitions, and wrote the product formula that ties the Riemann zeta function to [[prime-numbers|prime numbers]]. In mechanics he formulated rigid-body motion and elastic curves; in optics, lunar theory, and naval science he was an applied mathematician avant la lettre. The Königsberg bridges paper founded graph theory by refusing to draw the city and drawing the relation instead. The working unity of his corpus is not a philosophy. It is a habit of turning any problem into calculation.`,
    lineage: `Basel, the Bernoulli household, Peter the Great's Academy, and Frederick II's Berlin Academy were the institutions. He married Katharina Gsell, fathered thirteen children, of whom five survived, and kept a workday that legend makes inhuman. D'Alembert and he corresponded as rivals and colleagues; Lagrange was a successor in Berlin. Catherine the Great brought him back to Russia. A fever in 1738 cost him an eye; a cataract in 1771 cost him the other; assistants, notably his sons and Niklaus Fuss, wrote as he dictated. The Opera Omnia, still being edited, is a monument to the idea that [[mathematics|mathematics]] can be a profession of continuous publication. Laplace's advice — read Euler, he is the master of us all — remains a syllabus. The Letters to a German Princess, written in Berlin, made him a public expositor of optics and [[physics|physics]]; the Institutiones calculi differentialis and integralis became textbooks the nineteenth century could not throw away.`,
    tension: `Formal manipulation of divergent series, infinitesimals without limit, and a faith that algebra survives [[infinity|infinity]] made later rigorists wince; much of Euler is true in a sense Cauchy had to invent. Priority is another haze: he found so much that "Euler's theorem" is a crowded name, and later writers sometimes rediscovered him with fanfare. Applied work for courts and academies raises the old question of mathematics in the service of power — ballistics, navigation, the prestige of enlightened monarchs. The afterlife is nevertheless unmatched in density. To learn calculus, generating functions, or the first page of graph theory is still, in large part, to learn Euler under other names. His name is a climate of [[mathematics|mathematics]], not a single theorem.`,
  },

  "prime-numbers": {
    lede: `Prime numbers are integers greater than one whose only positive divisors are one and themselves: 2, 3, 5, 7, 11, and then an irregular spray that never ends. Euclid proved the infinitude; the fundamental theorem of arithmetic makes them the atoms of multiplication. Their distribution is regular on average — about x / ln x primes below x — and wild in the gaps, a tension [[riemann|Riemann]] encoded in the zeros of zeta. They are the raw material of modern [[cryptography|cryptography]], where the ease of multiplying large primes and the difficulty of factoring the product is a lock.`,
    idea: `A prime cannot be written as a product of smaller integers greater than one; a composite can, uniquely, once order is ignored. This uniqueness is the fundamental theorem, known in some form to Euclid and proved with modern care by Gauss in the Disquisitiones. Residual patterns — primes congruent to 3 mod 4, twin primes differing by 2, primes of the form n² + 1 — generate conjectures of very different status. Dirichlet's theorem guarantees infinitely many primes in coprime arithmetic progressions. Goldbach's conjecture, that every even integer greater than 2 is a sum of two primes, is verified far beyond computational doubt and unproved. The sieve of Eratosthenes is the ancient listing algorithm; the AKS test of 2002 showed primality is in P; factoring remains, so far, hard enough to run the internet's locks. Analytic tools convert the characteristic function of primes into a complex landscape whose peaks and zeros are the subject's true geometry.`,
    lineage: `Euclid's Elements, Book IX, Proposition 20, is the infinitude proof by contradiction: given any finite list, multiply, add one, and extract a new prime factor. Eratosthenes sieved. Fermat, Mersenne, and Euler hunted special forms; Euler's product ζ(s) = Π (1 − p^{−s})^{−1} revealed that primes know the harmonic series. Gauss guessed the logarithmic density from tables; Chebyshev bounded it; Hadamard and de la Vallée Poussin proved it in 1896. Vinogradov, Chen, Zhang Yitang (bounded gaps, 2013), and Maynard pushed the additive side. RSA, in 1977, turned the multiplicative difficulty into a public-key protocol. The Clay Millennium list placed the Riemann hypothesis among seven problems, a celebrity that has not shortened the line. Cramér's probabilistic model, and the Riemann–von Mangoldt explicit formula, taught the twentieth century to treat the primes as a random sequence with a deterministic skeleton, a dual vision [[probability|probability]] still exploits.`,
    tension: `Are primes a natural kind or an artifact of base-ten listing? The definition is robust across notations, but many of the famous conjectures may be true for "probabilistic" reasons that are not proofs. Cryptographic use creates a strange dual: number theorists celebrate factoring breakthroughs that security engineers dread. Quantum algorithms, Shor's in particular, threaten the dual if large quantum computers arrive. Another tension is aesthetic: the sequence looks random locally and lawlike globally, and no one has a definition of randomness that makes that sentence a theorem. Primes remain elementary to define and, at the frontier, among the least elementary objects in [[number-theory|number theory]]. Even the definition has an edge case that delights pedants: 1 was once called prime, then excluded so unique factorization would live, a reminder that [[mathematics|mathematics]] legislates its atoms as well as discovering them.`,
  },

  "set-theory": {
    lede: `Set theory is the official foundation of [[mathematics|mathematics]] and the stage on which [[infinity|infinity]] was made precise. A set is a collection determined by its elements; from empty set, pairing, union, power set, and infinity, Zermelo–Fraenkel axioms (with or without choice) reconstruct numbers, functions, spaces, and almost every object a working mathematician names. Cantor, in the 1870s, showed that infinities come in sizes; Russell's paradox of 1901 showed that "the set of all sets that do not contain themselves" cannot be a set. [[godel|Gödel]] and Cohen proved that the continuum hypothesis is independent of the standard axioms.`,
    idea: `Naive comprehension — for any property, the set of things with that property — collapses into paradox. Axiomatic set theory replaces it with controlled constructions: you may take subsets of existing sets (separation), images of existing sets (replacement), and the set of all subsets (power set), but you may not gather "everything." Ordinals generalize counting past the finite; cardinals measure size; aleph-null is the countable infinity of the integers, and Cantor's diagonal argument shows that the reals are strictly larger. The axiom of choice, isolated by Zermelo in 1904, says one may pick simultaneously from any family of nonempty sets; it is equivalent to Zorn's lemma and to the well-ordering theorem, and it proves theorems (a basis for every vector space, nonmeasurable sets) that some mathematicians would rather not own. Forcing, Cohen's 1963 method, builds models where extra axioms hold or fail, turning independence into a craft. The working idea is that mathematics can be rewritten as talk about membership, and that the rewrite reveals choices that had looked like facts.`,
    lineage: `Cantor's 1874 paper on the non-denumerability of the reals opened the subject; his later correspondence with Dedekind, and the Beiträge of 1895–97, built transfinite arithmetic. Hilbert defended the paradise Cantor created; Kronecker refused it. Zermelo axiomatized in 1908; Fraenkel and Skolem added replacement; von Neumann, Bernays, and Gödel offered class-set theories. Bourbaki took ZF as the silent prologue to the Éléments. Large cardinals — inaccessible, measurable, supercompact — became a ladder of consistency strength investigated by Tarski, Scott, Martin, Woodin, and others. A rival foundation, type theory and now homotopy type theory, proposes that spaces and proofs, not sets, are primitive. The basement has competitors. Cohen's 1963 forcing, announced at Stanford, ended Gödel's hope that the constructible universe was the true one; Woodin's program on Ω-logic is among the later attempts to name new axioms that would decide the continuum.`,
    tension: `If the continuum hypothesis has no answer in ZF, is there a fact of the matter about how many reals there are? Platonists, Gödel among them, hope for new axioms that will settle it; formalists treat independence as the answer. Choice splits analysis: with it, one has a Hahn–Banach theorem and a Banach–Tarski paradox; without it, one has models where every set of reals is measurable. Foundational anxiety rarely stops a working geometer, which is itself a sociological fact the subject must swallow. [[logic|Logic]] and [[proof|proof]] theory ask whether set theory is the right basement or merely the historically victorious one. The tension is that a foundation which admits many infinities cannot, by itself, tell you which infinity you meant.`,
  },

  "chaos-theory": {
    lede: `Chaos theory studies deterministic systems that forget their initial conditions exponentially fast: the butterfly, the weather, the dripping tap, the three-body problem Poincaré could not tame. Sensitivity to initial conditions, dense periodic orbits, and mixing are the usual symptoms; strange attractors, with fractal dimension, are the portraits. Edward Lorenz, in 1963, truncated a convection model to three equations and found that rounded-off data refused to replay. The subject sits between [[calculus|calculus]] (because the laws are differential equations) and [[emergence|emergence]] (because the behavior is not in any one term). It is order, but not the order a nineteenth-century determinist had paid for.`,
    idea: `A dynamical system is a rule — a map or a flow — iterating a state space. Lyapunov exponents measure how nearby trajectories diverge; a positive exponent is the quantitative signature of chaos. Poincaré sections cut a continuous flow into a discrete map one can draw. The logistic map x ↦ rx(1 − x), a cartoon of population, undergoes period-doubling as r grows; Feigenbaum showed in 1978 that the doublings converge at a universal rate, the same number appearing in fluids and in electronic circuits. Strange attractors, such as Lorenz's butterfly and the Hénon map, occupy volume zero yet have structure at every scale. Chaos is not noise: the rule is exact, the unpredictability is geometric, and short-term forecast can still be excellent. The working idea is that determinism and predictability came apart, and that [[calculus|calculus]] had contained this surprise since Newton wrote down gravity for more than two bodies.`,
    lineage: `Newton's two-body problem is integrable; the three-body problem is not. Poincaré, in his prize memoir on the n-body problem (1890, after a famous error and correction), discovered homoclinic tangles and the impossibility of closed-form celestial mechanics. Hadamard studied geodesic flows on negative curvature. Birkhoff, Kolmogorov, Arnold, and Moser built KAM theory: much of a nearly integrable system survives as quasiperiodic motion, with chaos in the gaps. Smale's horseshoe made a geometric engine of stretching and folding. Lorenz's 1963 paper in the Journal of the Atmospheric Sciences went unread by mathematicians for years. Yorke popularized the word chaos in 1975; Mandelbrot supplied fractals as the visual dialect; Ruelle and Takens proposed strange attractors as a route to turbulence, rivaling Landau's cascade. May's 1976 Nature paper on simple nonlinear models showed ecologists that a logistic map could oscillate and then go wild; Gleick's popular Chaos of 1987 carried Lorenz and Feigenbaum into public speech, for better and worse.`,
    tension: `Not every irregular time series is chaotic; distinguishing chaos from noise in finite data is a cottage industry of false positives. Popular speech treats the butterfly effect as a sermon on fragility, while the mathematics is about exponential maps and invariant measures. Quantum systems, with unitary evolution, complicate the metaphor: sensitive dependence must be redefined, and decoherence does some of the work classical stretching did. In climate science, chaos limits weather prediction to days but does not forbid climate statistics, a distinction politics likes to blur. The open problem is turbulence itself — whether Navier–Stokes solutions stay smooth, a Clay prize, and how a deterministic continuum equation manufactures the mess of a waterfall.`,
  },

  "category-theory": {
    lede: `Category theory is mathematics about mathematics: objects and arrows, composition of arrows, and what is preserved when names change. Eilenberg and Mac Lane introduced categories, functors, and natural transformations in 1945 to make precise the phrase "natural" in algebraic [[topology|topology]]. A category is a collection of objects and morphisms with associative composition and identities; a functor sends one category into another; a natural transformation is a morphism of functors. The subject became a foundation-candidate, a language for algebraic geometry after Grothendieck, and a surprising partner of [[logic|logic]] and of functional programming.`,
    idea: `The slogan is to take morphisms as seriously as objects. Isomorphism becomes the right equality: two objects are the same, for working purposes, when arrows between them invert. Universal properties characterize objects by how they talk to others — products, coproducts, limits, adjoints — without committing to an internal construction. Yoneda's lemma says an object is determined by the morphisms into it, a sentence that recasts representation as geometry. Abelian categories axiomatize homological algebra; monoidal categories axiomatize tensor; toposes axiomatize a universe of sets with its own internal [[logic|logic]]. In computer science, types and functions form categories; monads, stolen from this language, now structure effectful code. The working idea is that sameness of structure is itself a structure, and that once you draw the arrows, many theorems become the same theorem drawn twice. Limits and colimits unify products, kernels, and gluings; adjoint functors, which Lawvere treated as the form of logical quantification, are the morphisms that feel like finding a best solution to a universal problem.`,
    lineage: `Homology in the 1940s needed a way to say that constructions were canonical. Eilenberg–Mac Lane provided it; Kan, Grothendieck, Lawvere, and Cartan amplified it. Grothendieck's Tohoku paper of 1957 and the later EGA rebuilt algebraic geometry in abelian categories and schemes; the "yoga of anabelian geometry" and motives pushed further. Lawvere's 1963 thesis treated the category of categories as a foundation and recast [[logic|logic]] as adjoints. Mac Lane's Categories for the Working Mathematician (1971) became the missionary text. Homotopy type theory and univalent foundations, in the twenty-first century, propose that spaces, paths, and higher categories are what mathematics was about all along. Functional languages — Haskell especially — imported the vocabulary until monad became a programmer's complaint and tool. Quillen's model categories, and later Lurie's Higher Topos Theory, moved the subject into homotopy, where a morphism can be inverted up to a higher cell rather than on the nose — a change of what [[proof|proof]] is allowed to identify.`,
    tension: `Critics call it abstract nonsense: a language that proves nothing a specialist did not know, at a cost in prerequisites. Advocates reply that the nonsense is the theorem, the identification of what had seemed distinct. Foundational ambition collides with ZF's incumbency; most mathematicians still speak set while writing diagrams. Higher category theory (∞-categories, quasicategories of Joyal and Lurie) is powerful and, to outsiders, forbiddingly technical, raising a sociological barrier that the original 1945 paper did not intend. The open question is whether the subject remains a lingua franca or becomes a specialty whose arrows point mostly inward. The atlas files it as a concept because it is a way of seeing, not a single result.`,
  },

  infinity: {
    lede: `Infinity is not one size. It is a family of endlessnesses, tamed by Cantor into cardinals and ordinals and still philosophically wild. Aristotle distinguished potential infinity — you can always go on — from actual infinity, which he refused as a completed thing. Galileo noticed that the squares of integers can be paired with the integers, a paradox of equinumerosity. Cantor's 1874 proof that the reals are not countable, and the 1891 diagonal argument, made actual infinities into mathematical objects with an arithmetic. [[set-theory|Set theory]] is the official habitat; [[calculus|calculus]] had used infinite processes for two centuries without agreeing on what an infinite set was.`,
    idea: `Two sets have the same cardinality when a bijection exists between them. The integers, the even integers, and the rationals all have cardinality ℵ₀, aleph-null. The reals have cardinality 2^{ℵ₀}, strictly larger; Cantor's theorem says the power set of any set is larger than the set, so there is no largest infinity. Ordinals extend counting: after all finite numbers comes ω, then ω + 1, then ω · 2, and so on into an endless hierarchy of well-ordered types. Hilbert's hotel, with countably many rooms, can still accommodate a new guest by shifting; it cannot, without further tricks, accommodate an uncountable coach tour. Infinitesimals — quantities smaller than any positive real — were expelled by Weierstrass, then restored as honest objects in Robinson's nonstandard analysis and, differently, in smooth infinitesimal analysis. The working idea is that "endless" is an ambiguous English word, and that [[mathematics|mathematics]] profits by splitting it until paradox becomes classification.`,
    lineage: `Zeno's paradoxes made infinite division a scandal for motion. Scholastic debates, Nicholas of Cusa, and Galileo's Two New Sciences kept the scandal warm. Newton and Leibniz used infinitesimals as working fictions; Berkeley mocked them as ghosts of departed quantities. Bolzano, in 1851, treated infinite sets with a care his century barely noticed. Cantor, against Kronecker's finitism, built transfinite numbers and was rewarded with depression, hostility, and eventual canonization. Hilbert declared, in 1926, that no one would expel us from Cantor's paradise. Brouwer's intuitionism refused completed infinities that could not be constructed; Wittgenstein circled the grammar of "and so on." Modern large-cardinal research continues Cantor's climb with hypotheses whose consistency is a matter of faith calibrated by inner models. Conway's surreal numbers, and Knuth's popularization of them, showed that infinities and infinitesimals could share an arithmetic richer than Cantor's; physicists, meanwhile, renormalize divergences without agreeing they have met an actual infinite.`,
    tension: `Does actual infinity exist, or is it a useful fiction of [[proof|proof]]? Physics may not decide: cosmological infinities are speculative, and a discrete spacetime would make physical infinity potential at best. In foundations, the continuum hypothesis asks whether any size sits between integers and reals; independence means the question is, relative to ZF, a fork rather than a fact. Teaching calculus requires infinite processes in the first semester and forbids infinite sets as objects until later, a pedagogical hypocrisy students feel. Mystical and theological uses of the word — the Absolute, the divine — borrow prestige the mathematics does not owe. The concept cannot yet do what poets ask of it: name a single Endless. It can only sort endlessnesses and refuse a last one.`,
  },

  proof: {
    lede: `Proof is the social technology by which mathematicians convert insight into shared certainty. A proof is not merely a calculation; it is an argument that a trained reader can, in principle, check, replay, and teach. [[euclid|Euclid]] made the template; Hilbert made the formalist dream of a finite certificate; [[godel|Gödel]] showed that certificates cannot capture all arithmetic truth. Lakatos, in Proofs and Refutations, treated proof as a dialogue with counterexamples rather than a one-way gift of light. The concept neighbors [[logic|logic]], [[set-theory|set theory]], and the theory of computation, where [[turing|Turing]] machines become the auditors.`,
    idea: `Informally, a proof is a sequence of statements, each an axiom, a hypothesis, or a consequence of earlier lines by an agreed rule. Formally, in a deductive system, it is a tree or sequence in a specified syntax, checkable by a mechanical procedure. Between these poles lives the working proof: written in a natural language stiffened with symbols, full of "clearly" and diagrams, aimed at a reader who already shares a culture. Correctness, surveyability, and explanatoriness come apart. Appel and Haken's 1976 four-color proof was correct enough to convince, too large to survey by hand, and, to some, not explanatory. Formalizations in Coq, Isabelle, and Lean now let machines check arguments humans find too long, including the Feit–Thompson odd-order theorem and substantial pieces of schemes. Wiles's proof of Fermat's Last Theorem, patched in 1994–95 with Taylor, was a human-scale argument that required an expert community to vet. The working idea is that certainty is produced, not found, and that the means of production have a history.`,
    lineage: `Greek dialectic, Aristotelian syllogism, and Euclidean synthesis are the ancient three. Islamic and Indian mathematicians proved, sometimes in other styles; al-Khwarizmi's algebra mixed recipes with justifications. The calculus of Newton and Leibniz ran ahead of proof until Cauchy, Weierstrass, and Dedekind caught it. Frege's Begriffsschrift of 1879, Peano's axioms, and Russell and Whitehead's Principia tried to make every step explicit and nearly collapsed under the weight. Hilbert asked for finitary consistency proofs; Gödel in 1931 limited the ask; Gentzen proved consistency of arithmetic with a transfinite induction that Hilbert's original finitism would not have allowed. Computer proof began as numerical checking, became interactive theorem proving, and now includes neural suggestion of steps — a new social fact about who, or what, is in the room. Lakatos's dialogue on Euler's formula made counterexample and concept-stretching part of the official story; MacIntyre, Voevodsky, and the Univalent Foundations program then asked whether identity itself should be a path in a space rather than a primitive of [[logic|logic]].`,
    tension: `If a machine checks a proof no human has read, whose knowledge is it? The question is [[philosophy|epistemology]] wearing a silicon mask, and it will not vanish as files grow. Constructivists refuse proofs that use excluded middle or choice to produce objects they cannot exhibit. Probabilistic and holographic proofs, in theoretical [[computing|computing]], certify with high probability rather than with deduction, a different bargain. Sociological critiques note that "shared certainty" is shared among those trained to share it, and that credit, gender, and language shape which proofs get read. Proof cannot yet do what Hilbert wanted: close [[mathematics|mathematics]] with a finite, surveyable guarantee of its own consistency. Gödel explained why. The practice continues, adjusted, because the alternative is not a deeper certainty. It is a quieter room.`,
  },

  "fourier-analysis": {
    lede: `Fourier analysis is the art of taking a signal apart into waves and putting the world back together from them. Joseph Fourier, in the Théorie analytique de la chaleur of 1822, claimed that an arbitrary function on an interval is a sum of sines and cosines; Dirichlet and Riemann spent decades asking when the claim is true. The subject is now the spectral backbone of [[calculus|calculus]], of [[linear-algebra|linear algebra]] (an orthonormal basis of eigenfunctions), and of [[information-theory|information theory]]. Quantum mechanics speaks in Fourier pairs of position and momentum; JPEG, MRI, and the Cooley–Tukey fast Fourier transform of 1965 speak in the same pairs.`,
    idea: `A periodic function, under conditions Dirichlet began to isolate, equals a trigonometric series whose coefficients are inner products against sines and cosines — integrals that extract the amplitude of each frequency. The Fourier transform extends the story from periodic functions to functions on the line, trading a discrete spectrum for a continuous density of frequencies. Plancherel's theorem makes the transform an isometry of L²; the inversion formula is the putting-back-together. Convolution in one domain is multiplication in the other, which is why filters are designed in frequency. On groups, Pontryagin duality generalizes the picture; on manifolds, eigenfunctions of the Laplacian play the role of waves. Discrete and fast transforms make the continuous theory computable in O(n log n) rather than O(n²). The working idea is that many operators — differentiation, translation-invariant filters, the heat equation — become transparent once the signal is written as a sum of their eigenvectors. Discrete Fourier analysis on finite abelian groups is the same idea in miniature, and it is why multiplying large integers, compressing images, and hearing pitch are one subject wearing three hats.`,
    lineage: `D'Alembert, Euler, and Daniel Bernoulli argued in the eighteenth century about the vibrating string and whether trigonometric series were general enough. Fourier, an administrator under Napoleon and a survivor of the Revolution, insisted they were, using heat as the laboratory. Cauchy, Dirichlet (1829), and Riemann (1854 Habilitation on trigonometric series) supplied conditions and counterexamples; Weierstrass produced a continuous nowhere-differentiable function as a lacunary series. Lebesgue's integral made L² the right home. Haar, Wiener, and Paley built the harmonic analysis of the twentieth century; Schwartz's distributions let one transform impulses. Cooley and Tukey, in 1965, rediscovered a fast algorithm Gauss had used for astronomy, and digital signal processing became a civilization. Wavelets, from Haar through Morlet, Mallat, and Daubechies, offered a localized competitor to global sines. Zygmund's treatise trained analysts in maximal functions and Calderón–Zygmund operators; Stein carried the subject into several complex variables, while engineers independently made the FFT a piece of industrial [[computing|computing]].`,
    tension: `Convergence is delicate: a Fourier series may diverge at a point even for a continuous function (du Bois-Reymond), and Carleson's theorem, that L² functions converge almost everywhere, was a 1966 triumph that does not make the pointwise picture elementary. Gibbs ringing near jumps is a practical scar. Choosing a basis is a political act in applied work: sines, wavelets, learned dictionaries, or neural implicit representations each privilege different features. Uncertainty principles, from Heisenberg to Donoho–Stark, forbid perfect localization in time and frequency at once, a limit that [[physics|physics]] and engineering share. Fourier analysis cannot, by itself, tell you which skeleton a given world wants. It only guarantees that, once you pick the waves, the coefficients will not keep secrets they could have told in that language.`,
  },

  biology: {
    lede: `Biology is the science of living systems, from molecules that copy themselves to planets that green. It occupies a continent of the [[knowledge-atlas|Knowledge Atlas]], bordering |chemistry only as weather, [[mind|mind]] at the nervous system, and [[systems|systems]] wherever [[emergence|emergence]] and [[networks|networks]] do explanatory work. Aristotle catalogued animals; [[linnaeus|Linnaeus]] named them; [[darwin|Darwin]] gave them a history; [[mendel|Mendel]] and [[franklin|Franklin]] gave that history a molecule. Interior ranges include [[evolution|evolution]], [[genetics|genetics]], [[neuroscience|neuroscience]], [[cell-biology|cell biology]], [[ecology|ecology]], and the still-open [[origin-of-life|origin of life]]. Life is not a substance. It is a set of processes that persist by copying, metabolizing, and erring.`,
    idea: `A living system maintains a boundary, runs a metabolism, and — in every lineage we know — stores heritable information that [[natural-selection|natural selection]] can edit. The cell is the unit of organization; [[dna|DNA]] (and sometimes RNA) is the unit of memory; the organism is a temporary coalition of both, plus a [[microbiome|microbiome]] that complicates the census. [[evolution|Evolution]] by [[natural-selection|natural selection]] explains adaptation without a designer; [[genetics|genetics]] explains how variants persist across generations; [[ecology|ecology]] explains how those generations eat, compete, and cooperate in a world of finite fluxes. [[photosynthesis|Photosynthesis]] writes sunlight into chemistry; [[protein-folding|protein folding]] writes sequence into shape; the [[immune-system|immune system]] writes encounters into memory. [[neuroscience|Neuroscience]] asks how wet circuits yield [[consciousness|consciousness]], a question that leaks into [[philosophy|philosophy]]. The hub's claim is modest and enormous: that these processes are one science because they share a history, a chemistry, and a logic of variation and descent. Model organisms — pea, fly, worm, zebrafish, Arabidopsis, E. coli — are the field's chosen microcosms, a bet that a few species can stand in for the tree if the questions are sharp enough.`,
    lineage: `Harvey measured the blood; Hooke named the cell in 1665; [[linnaeus|Linnaeus]] published Systema Naturae in 1735 and made naming a nested art. [[pasteur|Pasteur]] buried spontaneous generation; Schwann, Schleiden, and Virchow made cell theory a slogan with teeth. [[darwin|Darwin]]'s Origin of 1859, Wallace's parallel insight, and the modern synthesis of Fisher, Haldane, Wright, and Dobzhansky fused [[natural-selection|natural selection]] with [[genetics|genetics]] after [[mendel|Mendel]] was rediscovered in 1900. The double helix of 1953, read from [[franklin|Franklin]]'s crystallography, turned heredity into [[information-theory|information theory]]'s cousin. Woese's three domains, Margulis's endosymbiosis, and the Human Genome Project of 2001–03 (draft to finishing) recast the tree as a web in places. CRISPR, single-cell sequencing, and cryo-electron microscopy are the present tense. The lineage is a relay of instruments as much as of ideas: microscope, gel, sequencer, collider of neither atoms nor empires but of proteins.`,
    tension: `Reduction and holism never sign a treaty. Molecular work can seem to dissolve organisms into sequences; [[ecology|ecology]] and evolutionary developmental biology put them back, sometimes with a slap. The species concept fractures across bacteria that trade genes; [[symbiosis|symbiosis]] and the [[microbiome|microbiome]] fracture the organism. Anthropogenic extinction makes [[biodiversity|biodiversity]] an ethical crisis as well as a count, pulling the hub toward [[philosophy|philosophy]] and policy. Origin questions remain experimentally stubborn. A further fault: human exceptionalism still warps the map of [[neuroscience|neuroscience]] and of [[consciousness|consciousness]]. Biology is a continent whose coastlines are chemical and whose interior politics are about what counts as an individual, a cause, and a life worth naming. A knockout mouse is not an ecology, yet [[evolution|evolution]] writes in both grammars.`,
  },

  evolution: {
    lede: `Evolution is descent with modification: the process that grew every known lineage from a common root, branching, merging, and sometimes vanishing. [[darwin|Darwin]] and Wallace proposed [[natural-selection|natural selection]] as the chief engine in 1858–59; [[genetics|genetics]] later supplied the heritable variation the engine requires. The fossil record, comparative anatomy, molecular sequences, and the [[cambrian-explosion|Cambrian explosion]] are among its archives. It is not a force pushing toward us. It is a filter and a genealogy, running wherever replicators differ in reproductive success. In the atlas it binds [[biology|biology]] to [[history|history]] in deep time, and to [[algorithms|algorithms]] whenever search is allowed to breed.`,
    idea: `Populations vary; some of that variation is heritable; some heritable variants leave more descendants; given time, the composition of the population changes. That is [[natural-selection|natural selection]] in one breath. Drift changes it without regard to fitness, especially in small populations; gene flow mixes; mutation and recombination supply novelty. Speciation — allopatric, sympatric, by polyploidy in plants — is how one lineage becomes two. Phylogeny is the resulting tree, except where hybridization and horizontal gene transfer make it a network, as in bacteria and in the ancient mergers of [[symbiosis|symbiosis]]. Macroevolution asks whether the same engines, scaled, explain the origin of body plans and the tempo of the [[cambrian-explosion|Cambrian explosion]]. Molecular clocks, imperfect, convert sequence divergence into time. The working idea is that adaptation looks like design because a blind filter, iterating over death, is very good at looking like a designer. Developmental constraint and phylogenetic inertia explain why selection does not produce every imaginable form; the panda's thumb, as Gould liked to say, is a jury-rig, not an engineer's first choice.`,
    lineage: `Buffon, Lamarck, and Erasmus Darwin offered transformist pictures before 1859; Lamarck's inheritance of acquired characters was the wrong mechanism with the right restlessness. Malthus's essay on population gave Charles Darwin a lever; the Beagle's biogeography gave him a museum. The 1858 Linnean Society papers, then the Origin, launched the argument. Mendelian [[genetics|genetics]], reconciled in the modern synthesis of the 1930s–40s, killed blending-inheritance objections. Kimura's 1968 neutral theory argued that much molecular change is drift. Gould and Eldredge, in 1972, proposed punctuated equilibrium; evo-devo, with homeobox genes in the 1980s, found deep homology in body-building kits. Genomic data now draw trees of life that Woese would recognize and then correct, especially at the root and among microbes. Paleontology, from Cuvier's extinctions to the Alvarez impact hypothesis of 1980, forced the field to admit catastrophe as a tempo alongside the gradualism Darwin preferred. Molecular phylogenetics then redrew kingdoms.`,
    tension: `Selectionists and neutralists still negotiate how much of the genome is sculpted versus drifting. Group selection, once nearly taboo, returned in debates over the evolution of cooperation and eusociality, with Hamilton's inclusive fitness as the rival bookkeeping. Cultural and symbolic evolution in humans — and now in machine populations — stretch the definition of replicator. Popular speech makes evolution a ladder or a destiny; the science makes it a tree that is mostly dead ends. The open problems are not whether it happened. They are how predictable it is, whether major transitions (cells, multicellularity, language) require extra principles, and how to talk about purpose without smuggling a watchmaker back in.`,
  },

  genetics: {
    lede: `Genetics is the architecture of heredity: how traits persist, recombine, and mutate across generations, from [[mendel|Mendel]]'s peas to sequenced genomes. Genes were first bookkeeping devices for 3:1 ratios; they became stretches of [[dna|DNA]] that specify [[protein-folding|proteins]] and regulatory RNAs; they are now also entries in databases that [[machine-learning|machine learning]] mines. Avery, MacLeod, and McCarty in 1944, then Hershey and Chase in 1952, showed that the transforming principle was DNA; Watson and Crick in 1953, using [[franklin|Franklin]]'s data, gave it a helix. The topic is the bridge between [[evolution|evolution]] and [[cell-biology|cell biology]], and the reason [[origin-of-life|origin-of-life]] research hunts a replicating polymer.`,
    idea: `Mendelian inheritance is particulate: alleles segregate, assort independently unless linked, and can be dominant, recessive, or something in between. Chromosomes are the physical vehicles; Morgan's Drosophila maps, beginning in 1910, made linkage a distance. The central dogma, as Crick stated it in 1958, is that information flows from nucleic acid to protein and not back — a rule reverse transcriptase complicates without cancelling. Transcription, splicing, translation, and epigenetic marks (methylation, histones) turn genotype into a regulated phenotype. Population genetics, in the hands of Fisher, Haldane, and Wright, gave allele frequencies a calculus: selection coefficients, effective population size, coalescents. Genomics industrializes the same ideas: GWAS hunt statistical associations; CRISPR–Cas9, adapted from bacterial immunity by Doudna, Charpentier, and others, edits the text. The working idea is that heredity is a code plus a cell to read it, and that variation in the code is the fuel [[natural-selection|natural selection]] burns. Quantitative genetics, from Galton's regressions (stripped of his politics) to Fisher's infinitesimal model, treats height and yield as sums of many small allelic effects, a picture GWAS has roughly confirmed and complicated.`,
    lineage: `[[mendel|Mendel]]'s 1866 paper slept in libraries until de Vries, Correns, and Tschermak rediscovered the ratios in 1900. Bateson named genetics; Johannsen distinguished genotype from phenotype. Muller used X-rays to mutagenize, proving genes were material. Beadle and Tatum's one-gene–one-enzyme slogan (1941) was too neat and exactly the right slogan. The phage group — Delbrück, Luria, Hershey — made microbes the model. Sanger sequenced insulin, then DNA; the Human Genome Project, officially completed in 2003, cost billions and now costs less than a sofa for a draft. RNA interference, induced pluripotent stem cells, and cheap sequencing shifted the field from rare Mendelian disease to the messy heritability of common traits. McClintock's jumping genes in maize, ignored then crowned, showed that genomes are not static texts. The 1977 discovery of split genes by Sharp and Roberts forced eukaryotes to splice. Genome-wide association studies, after 2005, made populations the new pea garden.`,
    tension: `Genetic determinism is the shadow: headlines that say "the gene for" betray a public that wants destiny and a science that deals in probabilities, polygenic scores, and environment. Heritability is often misread as immutability. Editing germline DNA raises an ethical wall that He Jiankui crashed in 2018. Missing heritability — the gap between twin studies and identified loci — remains a quantitative puzzle. Horizontal gene transfer and epigenetic inheritance complicate the Mendelian cartoon without restoring Lamarck as he hoped to be restored. Genetics cannot yet predict an organism from a sequence except in the simplest of cases, because [[protein-folding|protein folding]], development, and [[ecology|ecology]] sit downstream, and they do not take dictation quietly.`,
  },

  neuroscience: {
    lede: `Neuroscience is the study of nervous systems: how wet circuits sense, decide, remember, and — in some animals — feel. Cajal, using Golgi's stain, established the neuron doctrine against a rival reticular theory; Hodgkin and Huxley, in 1952, wrote the action potential as a set of equations in sodium and potassium. The topic now runs from ion channels to [[consciousness|consciousness]], from Aplysia's gill withdrawal to human fMRI. It neighbors [[mind|mind]], [[biology|biology]], and the artificial [[networks|networks]] of [[machine-learning|machine learning]], which borrowed a metaphor and then a set of algorithms.`,
    idea: `Neurons integrate synaptic currents and, crossing threshold, fire spikes that release transmitter onto others. Circuits — retina, hippocampus, cortex, ganglia of invertebrates — implement filters, memories, and policies. Hebb's 1949 slogan, that cells that fire together wire together, became LTP and STDP in the hippocampus and cortex. Systems neuroscience maps receptive fields (Hubel and Wiesel's orientation columns), place cells (O'Keefe), grid cells (Moser and Moser), and dopaminergic prediction errors (Schultz). Cognitive and affective neuroscience ask how those circuits support attention, [[consciousness|consciousness]], and value. Methods define eras: Golgi stain, microelectrode, patch clamp (Neher and Sakmann), calcium imaging, optogenetics (Deisseroth, Boyden, and others), and connectomics that slice and reconstruct. Computational neuroscience writes the same facts as dynamical systems and as statistical inference, sometimes as a Bayesian brain. The working idea is that explanation in this field is multi-scale by necessity: a memory is a synapse, a circuit, and a life. Large-scale recordings, from tetrodes to Neuropixels, now watch hundreds of cells at once, forcing theories to predict populations rather than a famous neuron in isolation.`,
    lineage: `Galvani's frogs, Helmholtz's nerve speeds, and Broca's tan named the nineteenth century. Cajal's drawings remain unsurpassed as both data and argument. Sherrington coined synapse; Adrian counted spikes. The mid-twentieth century belonged to biophysics and to behaviorism's rivals, then to the cognitive turn. Kandel's reduction of learning to Aplysia synapses showed that a molecular biology of memory was not a category error. The decade of the brain, the BRAIN Initiative, and the Human Connectome Project are bureaucratic descendants of that wager. Clinical neurology and psychiatry remain the unpaid bills: Alzheimer's plaques, depression's many doors, and the fact that we can name a circuit more easily than we can heal it. Pavlov's salivation, Lashley's failed search for the engram, and Hebb's assemblies are the behavioral grandparents. Mountcastle's columns, and the later connectomic reconstructions of C. elegans and Drosophila, tried to make the wiring diagram a readable sentence of [[biology|biology]].`,
    tension: `The hard problem of [[consciousness|consciousness]] sits on the field like a dare from [[philosophy|philosophy]]: explaining report, attention, and integrated information is not yet explaining why there is something it is like. Localization versus distributed coding is a recurring civil war; every "center for" is later a network. Animal models both reveal and mislead; organoids raise ethics. AI systems now match and exceed human performance on perceptual benchmarks without spiking neurons, which either demotes the wet details or shows that the field confused implementation with function. Reduction to molecules never quite reaches a person. Neuroscience cannot yet say which grain of description is the one that will make [[mind|mind]] a chapter rather than a neighbor.`,
  },

  "cell-biology": {
    lede: `Cell biology is the science of life's unit of organization: membranes, organelles, traffic, and the metabolism that keeps a far-from-equilibrium droplet intact. Robert Hooke named cells in cork in 1665; Schleiden and Schwann, in 1838–39, made them universal; Virchow, in 1855, insisted they come from cells. The topic is where [[dna|DNA]] is transcribed, where [[protein-folding|protein folding]] meets chaperones, where mitochondria and chloroplasts betray an ancient [[symbiosis|symbiosis]]. It neighbors [[origin-of-life|origin of life]] because any account of abiogenesis must eventually produce a bounded metabolizing compartment, and it neighbors the [[microbiome|microbiome]] because many of the cells that matter to you are not you.`,
    idea: `A cell is a volume of chemistry fenced by a lipid bilayer that leaks on purpose. Eukaryotic cells further compartmentalize: nucleus for the genome, endoplasmic reticulum and Golgi for secretion (Palade's pathway), mitochondria for ATP, lysosomes for digestion, cytoskeleton for shape and mitosis. Prokaryotes do without most of these rooms and still run the planet. Information flows from genome to proteome; energy flows from gradients — proton-motive force, as Mitchell argued in 1961 — to biosynthesis. Signaling pathways (phosphorylation cascades, G-protein receptors, morphogens) let cells know where they are in a body. The cell cycle, with cyclins and checkpoints (Hartwell, Hunt, Nurse), is a clock that can become cancer when the checkpoints fail. The working idea is that biochemistry becomes biology only when it is spatially addressed: the same molecule means different things on different sides of a membrane. Traffic between organelles runs on SNARE proteins, coats, and motors along microtubules; Rothman's fusion assays and Schekman's yeast secrets made that logistics a Nobel plot rather than a metaphor.`,
    lineage: `Leeuwenhoek saw animalcules; Hooke saw boxes. Cell theory waited for better lenses and for a nineteenth-century taste for units. Electron microscopy, after the 1930s, opened the ultrastructural zoo that Palade, Porter, and Sjöstrand catalogued. The fluid mosaic model of Singer and Nicolson (1972) made membranes a sea of proteins. Blobel’s signal hypothesis explained how proteins find their rooms. Endosymbiotic theory, championed by Lynn Margulis from 1967 against fierce resistance, made mitochondria and chloroplasts captives of an archaeal host — a [[symbiosis|symbiosis]] written into every eukaryotic textbook. Live-cell imaging and CRISPR screens now treat the cell as a factory one can watch and rewire. Tissue culture, from Harrison's hanging drops to Eagle's medium, made the cell an in-vitro animal. Fluorescent proteins, after Shimomura, Chalfie, and Tsien, let hidden compartments report in color. The CRISPR era turned the nucleus into an editable file.`,
    tension: `The cell is a unit until it is not: syncytia, biofilms, and chimeric organisms mock the census. Reduction to pathways on a whiteboard misses crowding, stochastic gene expression, and the physical chemistry of phase-separated condensates that the last decade rediscovered. Stem-cell and organoid research blur the line between analysis and manufacture, and therefore between science and engineering of persons. Cancer is cell biology's most expensive open problem: a Darwinian process inside a body, as Nowell argued in 1976, not merely a signaling error. Cell biology cannot yet start a cell from purified parts that stay alive, which is why [[origin-of-life|origin of life]] remains a neighbor rather than a solved special case.`,
  },

  ecology: {
    lede: `Ecology is the science of relations among organisms and their worlds: energy, nutrients, niches, disturbance, collapse, and recovery. Ernst Haeckel coined Oekologie in 1866 as the economy of nature; Tansley named the ecosystem in 1935; Elton, Hutchinson, and MacArthur gave niches a geometry. The topic is where [[biology|biology]] meets [[systems|systems]], [[networks|networks]], and [[photosynthesis|photosynthesis]] as a planetary flux. [[biodiversity|Biodiversity]] is one of its counts; [[symbiosis|symbiosis]] and the [[microbiome|microbiome]] are two of its social forms. It is not nature writing. It is accounting with living variables, delays, and feedbacks that do not care about the accountant.`,
    idea: `Energy enters most ecosystems as sunlight captured by [[photosynthesis|photosynthesis]] and leaves as heat; materials cycle. Food webs are graphs of who eats whom, with trophic levels as a rough height and omnivory as a smear. Population models, from Verhulst's logistic to Lotka–Volterra, are cartoons that sometimes predict; metapopulations and island biogeography (MacArthur and Wilson, 1967) add space. Succession, disturbance regimes, and keystone species (Paine's seastars) show that composition is a history, not an equilibrium gift. Nutrient limitation — Liebig's barrel, Redfield ratios in the sea — ties ecology to geochemistry. Human economies are now a dominant ecological force, which is why the Anthropocene is an ecological claim as well as a geological bet. The working idea is that organisms make their environments as surely as environments make organisms, a reciprocity Lewontin insisted on and that niche-construction theory tries to measure. Biodiversity–ecosystem-function experiments, such as Tilman's grasslands at Cedar Creek, test whether more species make a plot more productive or more stable, a question [[biodiversity|biodiversity]] politics badly wants answered in one direction.`,
    lineage: `Natural history is the deep past; Humboldt's isothermal maps and plant geography are a hinge. Haeckel's coinage, Warming's plant ecology, and Clements's superorganism climax (later battered by Gleason) set early arguments. Lindeman's 1942 trophic-dynamic paper put calories into the web. The Odum brothers scaled ecosystems to energy diagrams; Hutchinson's "homage to Santa Rosalia" asked why there are so many kinds of animals. Holling distinguished resilience from stability; Levin wrote about pattern and scale. Conservation biology, in Soulé's framing, made the field a crisis discipline. Remote sensing, environmental DNA, and trait databases now let ecology run at planetary resolution without abandoning the quadrat. Darwin's entangled bank is an ancestor; Warming's Oecology of Plants of 1895 is another. The International Biological Program of the 1960s tried to industrialize ecosystem measurement, with mixed success and a rich paper trail in [[systems|systems]] thinking.`,
    tension: `Complexity is not a result in ecology; it is the starting weather, and models that close must lie a little. Equilibrium metaphors (balance of nature) still haunt policy after the science moved to nonequilibrium and multiple stable states. The tension between controlled experiment and irreducible particularity — this lake, this year — never dissolves. Invasive-species ethics, rewilding, and assisted migration are value disputes wearing data. Climate change accelerates baselines so that "restoration" loses its reference. Ecology cannot yet say, with the confidence [[physics|physics]] enjoys, which simplifications are the right ones; it can say which ones have already failed. That is a kind of knowledge, and it is harder to sell.`,
  },

  "origin-of-life": {
    lede: `The origin of life is the still-open question of how chemistry crossed the threshold into Darwinian [[evolution|evolution]]. [[pasteur|Pasteur]] in the 1860s buried spontaneous generation for microbes; he did not explain the first microbe. Oparin and Haldane, in the 1920s, imagined a reducing soup; Miller and Urey, in 1953, sparked amino acids from it. The topic sits at the seam of [[biology|biology]], |chemistry, and [[entropy|entropy]]: a living cell is a locally ordered, far-from-equilibrium system that pays its bill in waste. RNA-world, metabolism-first, and compartment-first scenarios compete, and the rock record is nearly silent for the relevant eon.`,
    idea: `Life as we know it couples a heredity polymer ([[dna|DNA]] or RNA) to a metabolism inside a boundary. Abiogenesis must invent some version of that triad without already possessing it — a bootstrap. The RNA world, named by Gilbert in 1986, bets that RNA once stored information and catalyzed its own chemistry; ribozymes and the ribosome's catalytic RNA are exhibits. Metabolism-first views, often sited at alkaline hydrothermal vents (Russell, Martin, Lane), bet that geochemical proton gradients prefigured Mitchell's chemiosmosis before genes existed. Compartments — fatty-acid vesicles, as in Szostak's work — keep replicators from sharing all their profits with cheats. Homochirality, the genetic code's mapping, and the last universal common ancestor (LUCA) are later riddles stacked on the first. The working idea is not a single spark. It is a series of chemical thresholds after which [[natural-selection|natural selection]] could, for the first time, be the author. Homochirality remains a special riddle: living amino acids are left-handed, sugars right-handed, and no consensus experiment has shown how a racemic world chose a side that [[evolution|evolution]] could then lock.`,
    lineage: `Aristotle's spontaneous generation lasted, in one form or another, until Pasteur's swan-neck flasks and Tyndall's sterilization. Darwin, in a letter to Hooker, imagined a warm little pond; he kept the Origin mostly clear of genesis. Oparin's 1924 booklet and Haldane's 1929 essay independently described a prebiotic broth. Miller, a graduate student of Urey, ran the spark flask that became a photograph. Orgel, Eigen, and Spiegelman studied replicating RNA; Cech and Altman found catalytic RNA in living cells. Wächtershäuser proposed iron–sulfur surfaces; Cairns-Smith proposed clay. Mars meteorites, Enceladus plumes, and exoplanet atmospheres have made the question comparative: not only how life started here, but how often chemistry is expected to trip. Ponnamperuma and Juan Oró's adenine-from-HCN work expanded the inventory of prebiotic molecules. Sutherland's cyanosulfidic chemistry, in the 2010s, offered routes to nucleotides that skip the RNA world's hardest steps, a claim still under vigorous review.`,
    tension: `No laboratory has produced a population of replicators that evolve open-endedly from plausible prebiotic feedstock, and claims otherwise tend to smuggle in purified reagents. The early Earth is a moving target: was the atmosphere reducing, was the ocean salty, were vents or ponds the vessels? Panspermia postpones the problem without dissolving it. Definitional quarrels — is a self-sustaining autocatalytic set already alive? — leak into [[philosophy|philosophy]] and into [[emergence|emergence]]. [[entropy|Entropy]] does not forbid life; it prices it; popular arguments that thermodynamics bans abiogenesis misread the bill. The topic cannot yet do the thing science news wants: name the hour and the recipe. It can constrain the kitchen, still located on Earth so far as anyone knows.`,
  },

  darwin: {
    lede: `Charles Darwin (1809–1882) assembled the evidence for common descent and proposed [[natural-selection|natural selection]] as its chief engine. Five years on HMS Beagle (1831–1836) gave him a travelling museum; twenty further years of notebooks, barnacles, and delay gave him a book. On the Origin of Species appeared in 1859, rushed to print after Alfred Russel Wallace sent a parallel insight from the Malay Archipelago. He is the central figure of [[evolution|evolution]] not because he was the first transformist, but because he made a mechanism and a mountain of evidence occupy the same volume. Descent of Man (1871) and the expression of the emotions followed the argument into human beings.`,
    idea: `Darwin's working theory had several moving parts: variation is abundant and heritable; populations overproduce relative to resources (the Malthusian insight); individuals differing in heritable traits leave different numbers of offspring; given geological time, this filter yields adaptation and divergence. Sexual selection, developed more fully in 1871, explained ornaments that ordinary survival would not. He had no correct genetics — blending inheritance was a standing objection, and [[mendel|Mendel]]'s paper of 1866 sat unread on his shelves in spirit if not in fact — yet he insisted variation was real and replenished. Biogeography (Galápagos mockingbirds, South American fossils of extinct megafauna beside living armadillos) was as important to him as the pigeon coop. The Origin is one long argument, as he said, not a single experiment. Its method is consilience: many classes of fact pointing the same way. Coral reefs, the formation of vegetable mould by worms, and the fertilization of orchids were not hobbies: they were tests of gradual agency, time, and coadaptation, the same tools as the Origin applied to objects a specialist might have dismissed.`,
    lineage: `Shrewsbury, Edinburgh medicine abandoned, Cambridge for the clergy, then Henslow's recommendation to FitzRoy. The Beagle circumnavigated; Lyell's Principles of Geology travelled in the cabin and taught him deep time. Marriage to Emma Wedgwood, Down House, chronic illness, and a correspondence of thousands of letters were the domestic machine. The 1858 Linnean Society meeting, with papers by Darwin and Wallace read in absentia, was quiet. The Origin was not. Huxley debated, Owen opposed, Gray Americanized, and the church split. Later life brought orchids, climbing plants, earthworms, and a gentle public manner that did not match the radicalism of the idea. He was buried in Westminster Abbey, an irony he might have measured in millimetres of worm-cast. Lyell's slow conversion, Henslow's mentorship, and the Athenaeum reviews are the social plot. Emma's religious reservations, written in a letter he kept, belong to the emotional plot. The 1860 Oxford debate, Huxley versus Wilberforce, became the public theatre he himself avoided.`,
    tension: `Darwin's name is used as a club in culture wars he did not volunteer for. Social Darwinism, a political reading he only partly encouraged, remains a stain that [[biology|biology]] must keep scraping. He was wrong about blending, about inheritance of some acquired habits, and about the pace at which the earth could deliver time (Kelvin's cooling ages pressed him). Wallace diverged on the human mind; Gould later accused the modern synthesis of hardening Darwin into pan-selectionism. The afterlife is nevertheless the frame of the life sciences: nothing in [[biology|biology]] makes sense except in the light of evolution, as Dobzhansky wrote, and the light is still Darwin's, filtered through [[genetics|genetics]] he did not possess.`,
  },

  mendel: {
    lede: `Gregor Mendel (1822–1884), Augustinian friar at Brno, counted peas and found the atoms of heredity. Between 1856 and 1863 he crossed Pisum sativum for seven traits, scored thousands of progeny, and reported 3:1 ratios in the second filial generation. Versuche über Pflanzen-Hybriden, read in 1865 and published in 1866, was cited almost not at all until 1900, when de Vries, Correns, and Tschermak independently recovered the laws. He is the founding figure of [[genetics|genetics]], a contemporary of [[darwin|Darwin]] who held the missing particulate theory in a monastic garden. The delay is itself a lesson in how a [[proof|proof]] can fail for lack of a reader.`,
    idea: `Mendel's working idea is that traits are carried by paired factors that segregate at gamete formation and recombine at fertilization, some dominating the appearance of others. Independent assortment — his second law — holds when factors lie on different chromosomes, a physical rider he could not have known. He used true-breeding lines, reciprocal crosses, and enough numbers to see ratios rather than anecdotes; Fisher's later statistical audit asked whether the numbers were too clean, a controversy that still flickers. The pea traits (seed form, cotyledon color, flower color, pod form, pod color, stem length, flower position) were chosen with a gardener's cunning: discontinuous, easy to score, and, luckily, mostly unlinked. He also worked with bees and with Hieracium, a hawkweed that reproduces apomictically and refused his laws, a failure that may have discouraged him. The idea survived the organism that betrayed it. He presented ratios as empirical laws, not as chromosomes, and he tested them against theory with a chi-like care that later statisticians recognized. The garden was a laboratory of controlled crosses, not a contemplative walk.`,
    lineage: `Born to a farming family in Heinzendorf (Hynčice), he failed the teachers' examination twice, found a home in the Abbey of St. Thomas, and studied physics and botany at Vienna under Doppler and Unger. The monastery was not a hermitage; it was a research institute with a meteorological station and a library. Nägeli, the botanist to whom Mendel sent seeds and explanations, steered him toward hawkweed and did not understand. Darwin never read him with uptake. In 1900 the simultaneous rediscovery made a legend of neglect; historians have since noted that the paper was not invisible, only unintelligible to a biology that lacked chromosomes as vehicles. Bateson became the evangelist; the chromosomal theory of Sutton and Boveri gave the factors a place to sit. The Natural History Society of Brünn published him in its proceedings, a respectable but provincial organ. Fisher, de Vries, and Bateson later fought over what he had meant; the chromosomal school of Morgan then gave the factors a place in the fly room of [[genetics|genetics]].`,
    tension: `Was Mendel lucky, or did he stop counting when the ratios sang? Fisher's 1936 suggestion of unconscious editing is neither proved nor fully dismissed. Another tension is mythic: the solitary monk versus a man embedded in a scientific abbey and a European network. His laws are the beginning of [[genetics|genetics]], not its map; continuous traits, epistasis, imprinting, and horizontal transfer all live outside the 3:1 frame. He did not refute Darwin and did not complete him; the modern synthesis needed both, plus mathematics Darwin feared and peas Darwin never grew. The afterlife is a ratio every biology student still plants, and a warning about papers that arrive before their vocabulary.`,
  },

  franklin: {
    lede: `Rosalind Franklin (1920–1958) made the double helix visible. At King's College London she and Raymond Gosling produced Photograph 51, an X-ray diffraction image of B-form [[dna|DNA]] whose cross of intensities told a helical story with ten base pairs per turn and the phosphates outside. Maurice Wilkins showed the image to James Watson; Watson and Crick's 1953 Nature model used her measurements, with a footnote that did not match the debt. She died of ovarian cancer at thirty-seven, four years before the Nobel Prize in Physiology or Medicine went to Watson, Crick, and Wilkins.`,
    idea: `Franklin was a physical chemist of carbons before she was a nucleic-acid crystallographer. Her Paris work on coal and graphite taught her to read disordered matter with X-rays; at King's she distinguished the wet B-form of DNA from the drier A-form and insisted that any model respect the quantitative intensity data, including an anti-helical period when the B-form evidence was still incomplete. Photograph 51, taken in 1952, is a beautiful piece of physics: layer lines, a missing fourth layer, and a strong 3.4-ångström meridional spot. She was moving toward a double helix of her own when Cambridge announced. Later, at Birkbeck, she built a school on the tobacco mosaic virus, showing RNA coiled within a protein helix — a second structural triumph less often printed on T-shirts. The working contribution is not a single photograph. It is a standard of evidence that the model-builders needed more than they first admitted.`,
    lineage: `Born in Notting Hill to a prominent Anglo-Jewish family, she studied at Newnham College, Cambridge, then war work on coal porosity, then Jacques Mering's lab in Paris. Randall's King's College unit was a tangle of unclear authority: Wilkins thought she was his assistant; she thought she had her own problem. Gendered exclusion from King's common rooms is documented, not folkloric. After DNA she declined bitterness in public and chose TMV and polio virus. Aaron Klug, her closest collaborator at Birkbeck, later received a Nobel Prize in part for work that continued hers; he also became her most careful historian. Watson's The Double Helix (1968) caricatured "Rosy"; subsequent biographies by Sayre, Maddox, and others rewrote the scene without turning her into a saint of pure method. Klug's 1968 Royal Society memoir, and the later opening of the King's archives, made the data trail public.`,
    tension: `Credit is the open wound. Would Franklin have solved the helix without Watson and Crick? Would they have solved it that spring without Photograph 51 and her MRC report? Counterfactuals are cheap; the paper trail of data transmission is not. A second tension is hagiography versus complexity: she was rigorous, sometimes wrong (the early anti-helical caution), and not working toward a race she had agreed to run. Nobel rules against posthumous awards locked her out in 1962; the rules do not explain the footnotes of 1953. In the atlas she stands as a reminder that [[dna|DNA]]'s discovery was an institution, not a picnic, and that [[genetics|genetics]] inherited a molecule whose image was taken by someone the prize could not, or would not, include.`,
  },

  pasteur: {
    lede: `Louis Pasteur (1822–1895) buried spontaneous generation, founded the germ theory of disease as a working program, and turned stereochemistry into a science of molecular handedness. Trained as a chemist, he noticed that tartrate crystals come in mirror forms that rotate light opposite ways, a fact he linked to living processes. Swan-neck flasks, anthrax and rabies vaccines, and the Pasteurization of wine and milk are the public monuments. He is a node of the [[microbiome|microbiome]], the [[immune-system|immune system]], and [[cell-biology|cell biology]] because he made microbes causal in a way the nineteenth century could industrialize. The Institut Pasteur, opened in 1888, is the afterlife as an institution.`,
    idea: `Pasteur's method was to trap an invisible cause in an apparatus that made it visible by its absence. The swan-neck flask admitted air but not dust; boiled broth stayed sterile until the neck was broken. Fermentation, he argued against Liebig, was a vital act of yeast, not a mere chemical decay; diseases of wine and of silkworms (pébrine, flacherie) yielded to the same insistence on specific organisms. Attenuated vaccines — fowl cholera by accident of a spoiled culture, anthrax at Pouilly-le-Fort in 1881, rabies in 1885 with Joseph Meister — founded immunology as practice before antibodies had names. He never saw a virus, yet rabies prophylaxis worked. The working idea is that the smallest living things are not accidents of broth. They are agents, and agents can be weakened into teachers of the [[immune-system|immune system]]. Optical activity as a signature of life — dissymmetric molecules produced by dissymmetric forces — remains a heuristic of [[origin-of-life|origin-of-life]] chemistry. He treated disease as a specific fermentation, a unification that made vaccines thinkable as attenuated ferments.`,
    lineage: `Dole, then Arbois, then the École Normale Supérieure; chairs at Strasbourg, Lille, and Paris. A stroke in 1868 partially paralyzed him; he continued. Pouchet defended spontaneous generation; the Académie des sciences, and public demonstrations, decided for Pasteur. Koch, in Germany, would sharpen postulates and pure culture; the two schools rivalled and completed each other. National politics — Alsace, the Franco-Prussian War, the prestige of French science — are not background. They are fuel. Late honors, a state funeral, and a crypt at the Institut made him a secular saint of the Third Republic. Notebooks unsealed later showed a more improvisational, sometimes overclaimed, laboratory than the legend. Jean-Baptiste Dumas was an early patron; the Lille commission on beet-alcohol and the silk districts of the south were his first applied theatres. Duclaux, Chamberland, and Roux turned the laboratory into a school, and the Institut into a global network of [[biology|biology]] as public health.`,
    tension: `Notebook scholarship (Geison and others) revealed that the anthrax public experiment used a method closer to Toussaint's than the oratory admitted, and that rabies protocols were adjusted in ways the published story smoothed. Heroic narrative and messy priority can both be true. Spontaneous generation is dead for organisms now on Earth; [[origin-of-life|origin of life]] is the question Pasteur postponed. Germ theory, triumphant against miasma, later had to make room for the [[microbiome|microbiome]] as ally rather than invader, and for diseases that are not infectious. Pasteur's afterlife in public health — pasteurization, vaccines, institutes — is so large that the man is easily replaced by a verb. The atlas keeps the chemist in view, stereoscope and all.`,
  },

  linnaeus: {
    lede: `Carl Linnaeus (1707–1778) gave [[biology|biology]] a nested language for life: kingdoms, classes, orders, genera, species, and the two-word name that still labels a specimen. Systema Naturae first appeared in 1735 as a pamphlet; the tenth edition of 1758 is the starting point of zoological nomenclature, as Species Plantarum of 1753 is for plants. He placed Homo sapiens among the primates with a candor that startled, and he filled the creation with a sexual system of plant classification that made botany a fashionable scandal. He is the namer of names, a figure of the Enlightenment whose hierarchies later [[evolution|evolution]] would reread as genealogies. [[biodiversity|Biodiversity]] still speaks Linnaean as a second tongue.`,
    idea: `Binomial nomenclature — Homo sapiens, Escherichia coli, Pisum sativum — is a database key invented before databases: genus plus specific epithet, unique enough to travel across languages. Linnaeus believed he was describing a created order, stable and hierarchical, with species as the genuine coins and genera as the mint's larger denominations. The sexual system of plants, counting stamens and pistils, was admittedly artificial, a key for identification rather than a map of affinity; he knew it, and still it organized the herbaria of Europe. He classified minerals and diseases too, an imperial appetite for listing. Lapland travels, correspondence with apostles who shipped skins and seeds, and the Uppsala garden made him a node in a physical [[networks|network]] of specimens. The working idea is that without stable names there is no cumulative natural history, only local folk taxonomies that cannot argue with one another. He diagnosed species by a short Latin phrase and a type, a practice the Codes still echo. The garden and the herbarium were instruments as much as the pen: without a dried specimen, a name is a rumor, and he knew it.`,
    lineage: `Born in Råshult, son of a pastor who garden-taught him, he studied at Lund and Uppsala, took a medical degree in the Netherlands, and published Systema Naturae in Leiden. Patronage from Rudbeck, then a professorship at Uppsala, then knighthood as Carl von Linné. He sent students — the apostles — to the Americas, Asia, and Africa; some died, some returned with boxes that rewrote the Systema. Buffon opposed his artificial cuts; later naturalists (Adanson, Jussieu, Cuvier) built more "natural" systems on anatomy. Darwin turned the nested boxes into a family tree; Willi Hennig's phylogenetic systematics would later demand that names track clades. The International Codes of nomenclature still date their laws from Linnaeus's editions, a legal afterlife few scientists enjoy. The Dutch years with Clifford's garden produced Hortus Cliffortianus, a luxurious folio. Later, the Linnean Society of London, founded in 1788, inherited his specimens and, in 1858, heard Darwin and Wallace in the room where his order still hung on the walls.`,
    tension: `The hierarchy he thought was God's is, after Darwin, a genealogical approximation with ranks that are conventions. Microbial life, horizontal gene transfer, and hybrids strain the species coin he minted. His racial classifications of humans, including ugly stereotypes in later editions, are not a side note; they entered scientific racism's toolbox. Naming as possession — plants extracted into European Latin — is a colonial fact that ethnobotany and indigenous data sovereignty now contest. Linnaeus cannot be discarded, because the language still runs, and cannot be simply celebrated, because the language was also a claim to own the book of nature. The atlas keeps him as the man who made listing a science, and listing a politics.`,
  },

  dna: {
    lede: `DNA is the molecule that stores hereditary information as a four-letter text that copies itself: adenine, thymine, guanine, cytosine, paired A–T and G–C down a double helix. Miescher isolated "nuclein" in 1869; Avery's group in 1944 and Hershey and Chase in 1952 showed it was the transforming principle; Watson and Crick in 1953, using [[franklin|Franklin]]'s crystallography, built the model that made replication a picture. The concept sits at the center of [[genetics|genetics]], [[cell-biology|cell biology]], and [[origin-of-life|origin of life]], and it is a cousin of [[information-theory|information theory]]: a polymer that is also a message. Sequence in, [[protein-folding|protein folding]] out, with RNA as the working intermediary.`,
    idea: `Two antiparallel sugar-phosphate backbones spiral, with base pairs as rungs; complementarity makes copying a matter of unzipping and filling. Semi-conservative replication, confirmed by Meselson and Stahl in 1958, was the helix's first experimental harvest. Transcription writes RNA; translation, in the ribosome, writes protein in the alphabet of twenty amino acids, a mapping Crick called the central dogma. Genomes are not only genes: they are landscapes of regulation, transposons, and, in eukaryotes, vast stretches whose function is still argued. Sequencing — Sanger's chain termination, then massively parallel short reads, then long nanopores — turned the molecule into a text that [[algorithms|algorithms]] align and that [[machine-learning|machine learning]] now annotates. DNA can also be material culture: forensic identity, ancient genomes of Neanderthals (Pääbo), and plasmids that move antibiotic resistance through the [[microbiome|microbiome]]. The working idea is that heredity has a chemistry, and the chemistry is linear, digital, and astonishingly stable in the dark of a spore.`,
    lineage: `Miescher's pus-soaked bandages in Tübingen are the unglamorous start. Levene described nucleotides and, wrongly, a repeating tetranucleotide, a model too stupid to be a gene. Griffith's 1928 transformation of pneumococci set the table; Avery, MacLeod, and McCarty served DNA. Pauling proposed a triple helix and missed; Franklin distinguished A and B forms; Watson and Crick, in Cambridge, built tin and cardboard until Chargaff's rules (A=T, G=C) clicked as pairing. Jacob and Monod added regulation; Southern blotted; Mullis amplified with PCR in 1983, a technique that remade forensics and diagnostics. The Human Genome Project, Celera's competition, and the $1000 genome are the industrialization of a structure first measured in ångströms. Chargaff's rules, Crick and Brenner's frameshift mutants, and Nirenberg and Khorana's cracking of the codon table made the helix a code rather than a sculpture. Berg's recombinant DNA, and the 1975 Asilomar meeting, then asked [[biology|biology]] to police its own scissors.`,
    tension: `The molecule is not the organism. Equating DNA with destiny ignores development, environment, epigenetics, and the fact that most traits are polygenic. Gene editing (CRISPR) makes the text writable, which is a medical hope and a eugenic peril. Junk DNA was declared, then partially undeclared by ENCODE, a public fight about what "function" means. RNA worlds and prions remind us that heredity is not DNA's monopoly. As an archival medium DNA is superb; as an explanation of life it is necessary and badly insufficient. The concept cannot yet tell you how a sequence becomes a sparrow, which is why [[biology|biology]] remains more than a library of strings. A sparrow is a development, not a download.`,
  },

  "natural-selection": {
    lede: `Natural selection is the filter: heritable variation plus differential reproduction yields design without a designer. [[darwin|Darwin]] and Wallace extracted the idea from biogeography, artificial selection, and Malthus; the modern synthesis gave it a price in allele frequencies. It is the central mechanism of [[evolution|evolution]], though not the only one — drift, constraint, and hitchhiking also write the record. Industrial melanism in Biston betularia, the Grants' finches on Daphne Major, and the standing crop of antibiotic resistance are among its demonstrations. In [[computing|computing]] it reappears as a search heuristic; in [[philosophy|philosophy]] it is the acid that eats teleology and then, carefully, returns function-talk as a shorthand.`,
    idea: `Whenever entities make copies with heritable differences, and some copies populate the next generation more than others, the population's composition shifts. Fitness is that difference in reproductive success, not a tautology if one can predict it from ecology before counting grandchildren. Selection may be directional, stabilizing, or disruptive; it may act on individuals, and — more contentiously — on genes, groups, or cultural variants. Sexual selection is selection arising from competition for mates rather than from survival. Inclusive fitness, Hamilton's 1964 bookkeeping, explains altruism toward kin without a group mind. At the molecular level, selection is inferred from dN/dS ratios, from selective sweeps that drag hitchhiking SNPs, and from convergence. The working idea is ruthlessly substrate-neutral: it applies to RNA molecules in a tube, to viruses, to learned songs, and to [[algorithms|algorithms]] that breed bit-strings, provided the three conditions hold. Artificial selection was Darwin's tutorial: pigeons, dogs, and cabbages showed that heritable change can be piled up by a breeder; nature, he argued, is a breeder with more time and no taste except survival and mates.`,
    lineage: `Breeders had selected for millennia without a theory of how nature could. Paley's watchmaker made the design argument vivid; Malthus made struggle vivid. Darwin's notebooks of the late 1830s already contain the wedge; Wallace's 1858 Ternate letter independently found it. Spencer's "survival of the fittest" named it badly. Fisher’s Genetical Theory of Natural Selection (1930), Haldane's papers, and Wright's adaptive landscapes mathematized it. Experimental evolution — Lenski's long-term E. coli populations, begun in 1988 — watches it in real time. Williams's Adaptation and Natural Selection (1966) policed sloppy group-selection talk; later multilevel models tried to let groups back in without sloppiness. Kettlewell's moths, later criticized for method, still stand as a public demonstration; Endler's guppies and the Grants' thirty years of beak measurements made field selection visible year by year. Lenski's flasks added thousands of asexual generations under a lab clock.`,
    tension: `If fitness is defined as whatever survives, selection explains nothing; the charge of tautology is answered by independent measures of the trait and the ecology, but popular speech still loops. Pan-selectionism — the habit of inventing a purpose for every nucleotide — met Kimura's neutral theory and lost some of the genome. Teleological language ("in order to") creeps back because it is short, and short language misleads. Applying selection to human societies without extreme care is how social Darwinism was born. The concept cannot by itself explain the origin of the replicators it requires; that bill is owed to [[origin-of-life|origin of life]]. It remains the best idea anyone has had about how purpose-like order appears in a world of [[entropy|entropy]].`,
  },

  photosynthesis: {
    lede: `Photosynthesis is the biochemical bridge that turns sunlight into chemical wealth and, as a side effect, oxygen into an atmosphere. Priestley, in 1771, found that mint restores air; Ingen-Housz, in 1779, showed that light and green parts are required. The Calvin–Benson cycle, mapped with carbon-14 at Berkeley after the Second World War, fixes CO₂ into sugar; photosystems II and I, sitting in thylakoid membranes, strip electrons from water and raise them with photons. Cyanobacteria ran an oxygenic version by about 2.4 billion years ago, the Great Oxidation Event that made aerobic [[cell-biology|cell biology]] possible. [[ecology|Ecology]] is, in energy terms, mostly a commentary on this reaction.`,
    idea: `Light reactions capture photons in chlorophyll and accessory pigments, pumping protons and making ATP and NADPH; dark reactions (which run in the light) use those reductants to carboxylate ribulose bisphosphate via Rubisco, the planet's most abundant enzyme and a notoriously confused one, which also oxygenates in photorespiration. C₄ and CAM plants invented spatial and temporal workarounds to that confusion. Oxygenic photosynthesis splits water and releases O₂; anoxygenic versions, older, use H₂S or organic donors and never made a breathable sky. Chloroplasts are captured cyanobacteria, a [[symbiosis|symbiosis]] that [[cell-biology|cell biology]] inherited. The quantum efficiency, action spectra (Engelmann's bacterial assay on a filament of algae), and the Z-scheme of Hill and Bendall are the biophysical plot. The working idea is that a photon of red light is enough, if channelled, to change the redox of the planet. Global net primary production, on the order of 100 petagrams of carbon a year, is this chemistry at planetary scale, split between phytoplankton and land plants, a flux [[ecology|ecology]] measures and climate models now must close.`,
    lineage: `Van Helmont weighed a willow and wrongly credited water alone. Priestley, Ingen-Housz, Senebier, and de Saussure assembled the gas exchange. Sachs saw starch form in illuminated chloroplasts. Blackman distinguished light and dark stages. Van Niel compared sulfur bacteria and green plants and guessed, correctly, that O₂ comes from water, confirmed by Ruben and Randall with ¹⁸O. Calvin, Benson, and Bassham walked carbon through paper chromatography. Emerson's red-drop and the two-photosystem idea followed. Structural biology, culminating in high-resolution photosystem crystals (Abrahams, Barber, Suga, Shen, and many others), made the water-splitting Mn₄Ca cluster a thing one can stare at. Artificial photosynthesis remains a promissory note for energy policy. Willstätter and Stoll studied chlorophyll as a pigment; Emerson and Arnold counted photons per oxygen in flashing light. The chemiosmotic link, Mitchell again, joined chloroplasts to mitochondria as two addresses of the same proton currency in [[cell-biology|cell biology]].`,
    tension: `Rubisco's inefficiency looks like a bad design and is a frozen accident of an anoxic past; engineering a better carboxylase is a cottage industry with limited field victories. Biofuel dreams collide with land use and with the fact that [[ecology|ecology]] already spends the surplus. Climate change is a perturbation of the same carbon the Calvin cycle once drew down into coal and oil. Photorespiration, CAM, and C₄ show that evolution found workarounds, not perfection. Photosynthesis cannot, by itself, close the human energy budget without agricultural and political choices the molecule does not make. It remains the most important chemical reaction on Earth that [[physics|physics]] would still recognize as electromagnetism meeting redox.`,
  },

  "immune-system": {
    lede: `The immune system is a distributed learning system that distinguishes self from other and remembers insults. Jenner’s 1796 cowpox inoculation, and [[pasteur|Pasteur]]'s attenuated vaccines, taught it before anyone knew its parts. Metchnikoff saw phagocytes eat; Ehrlich imagined antibodies as side-chains; Burnet’s clonal selection theory of 1957 explained how a repertoire of lymphocytes can be both specific and tolerant. Innate and adaptive arms, MHC restriction, and immunological memory are the modern plot. It neighbors [[cell-biology|cell biology]], the [[microbiome|microbiome]], and [[networks|networks]], because recognition is a graph of receptors, cytokines, and checkpoints that can heal or inflame.`,
    idea: `Innate immunity — barriers, complement, Toll-like receptors that Janeway predicted and Beutler and Hoffmann helped reveal — responds in hours to microbial patterns. Adaptive immunity, in jawed vertebrates, rearranges antigen-receptor genes (Tonegawa) to generate a vast library of B-cell antibodies and T-cell receptors, then clones the useful few. MHC molecules present peptides so T cells can inspect the interior of cells; failure of that inspection is a tumor's hope and a virus's career. Tolerance is taught in the thymus and maintained in the periphery; autoimmunity is its failure; allergy is a misfire at innocuous antigens. Vaccines exploit memory; checkpoint inhibitors (Allison, Honjo) exploit the brakes tumors pull. The working idea is that defense in a changing microbial world cannot be a fixed list of enemies. It must be a generative grammar plus a school. Affinity maturation in germinal centers is Darwinism in a lymph node: B cells mutate their antibody genes and compete for antigen, a speeded [[natural-selection|natural selection]] that can outpace a virus if luck and time allow.`,
    lineage: `Variolation in China and the Ottoman world preceded Jenner. Pasteur, Koch, Behring (antitoxin), and Roux built humoral immunity as serum. Metchnikoff, in Messina, watched starfish larvae engulf thorns and named phagocytosis. Landsteiner's blood groups made compatibility a chemistry. Medawar's acquired tolerance, Jerne's selection ideas, and Burnet's clones gave the adaptive system a Darwinian logic. The 1970s–90s brought monoclonal antibodies (Köhler and Milstein), HIV as a teacher of T-cell necessity, and the mapping of cytokine storms. COVID-19 was a planetary examination of mRNA vaccines and of immunological inequality. Jenner published in 1798; Pasteur's rabies work of 1885 made attenuation a method. The smallpox eradication certified in 1980 is the largest success of the idea. Molecular immunology then found V(D)J recombination, dendritic cells (Steinman), and the inflammasome as innate sensors. [[pasteur|Pasteur]] remains the public statue of that lineage.`,
    tension: `Self and nonself, Burnet's axis, is too clean: the [[microbiome|microbiome]] is nonself we must tolerate, pregnancy is a graft, and danger theories (Matzinger) argue that the system senses damage more than foreigners. Hyperinflammation and immunosuppression are opposite failures of the same network. Autoimmunity and cancer immunotherapy are the two faces of turning the system up. Evolutionary mismatch — hygiene hypotheses, novel allergens — may explain some of the modern caseload. The immune system cannot yet be programmed with the precision of a compiler; we still poke it with antigens and hope the grammar parses. That hope, empirically rich, is not the same as understanding. Vaccination remains the most successful public bet the system has made.`,
  },

  "cambrian-explosion": {
    lede: `The Cambrian explosion is the geologically brief interval, beginning around 541 million years ago, when most animal body plans appear in the rock. Trilobites, anomalocaridids, priapulids, and the first chordates show up with a suddenness that troubled [[darwin|Darwin]] and still organizes debate in [[evolution|evolution]]. The Burgess Shale, found by Walcott in 1909, and Chengjiang in China, preserve soft parts that ordinary fossilization forgets. It is not the origin of life, which is older by billions of years, nor the origin of animals, whose molecular clocks often tick in the Ediacaran or before. It is the origin of a recognizable zoo, and of an ecology of shells, eyes, and burrows.`,
    idea: `Something changed in the early Cambrian: skeletons, predation, bioturbation, and developmental toolkits become visible together. Explanations come in clusters. Oxygen finally supported large, active metazoans. A developmental revolution — co-option of Hox and other regulatory genes — made modular body plans writable. Ecological feedback, an arms race of seeing and fleeing, as Parker argued with eyes, amplified disparity. Snowball Earth aftermaths and true polar wander are the geophysical candidates. The fossil pattern may also be partly taphonomic: biomineralization made the already-living suddenly preservable. Gould's Wonderful Life (1989) read Burgess disparity as a lottery of body plans, most of which lost; Conway Morris read the same fossils as a funnel toward convergence. The working idea is that macroevolution can, at times, be fast in the rock without being magic in the genome. Trace fossils — Treptichnus, Rusophycus — show that behavior, not only bone, changes in the record. Small shelly fossils precede the Burgess celebrities, so the explosion has a prologue of tiny armor as well as a climax of large predators.`,
    lineage: `Buckland, Sedgwick (who named the Cambrian), and Darwin noted the abrupt appearance of fossils and offered the incompleteness of the record as balm. Walcott's Burgess quarries, high in the Canadian Rockies, were reinterpreted by Whittington, Conway Morris, and Whittington's Cambridge school in the 1970s as a theatre of vanished designs (Hallucigenia, famously inverted in reconstruction). Cloudina and other Ediacaran skeletons, plus the trace fossil Treptichnus pedum, blurred the boundary. Shu, Zhang, and others at Chengjiang found early vertebrates. Molecular phylogenies and molecular clocks, calibrated poorly, keep disagreeing with the rock about how long animals were small and soft before they were large and hard. Fortey's trilobites, Butterfield's taphonomy, and Erwin's geochemical syntheses are the modern apparatus. The Ediacaran biota, named from Australia's hills, remains a quarrel: failed experiments, or animals we still cannot place on the tree of [[evolution|evolution]]?`,
    tension: `Explosion or slow fuse? If clocks are right, the Cambrian is a preservation and ecological event more than a phylogenetic one; if the rocks are taken at face value, something genuinely pulsed. Gould's contingency — replaying life's tape — remains a philosophical live wire, opposed by convergence enthusiasts. Defining a "body plan" without circularity is harder than museum labels suggest. Anthropic selection (we are the descendants who notice) lurks. The concept cannot yet assign weights to oxygen, genes, and ecology, which means the most famous burst in [[biodiversity|biodiversity]] is still a committee of causes. That is an honest incompleteness, not a failure to have looked. [[darwin|Darwin]] would have recognized the problem and not the new phyla.`,
  },

  "protein-folding": {
    lede: `Protein folding is how a string of amino acids becomes a shape, and why that shape is almost all of biochemistry: catalysis, signaling, structure, transport. Christian Anfinsen, in the 1960s, showed that ribonuclease can refold from a denatured chain, implying that sequence determines structure under physiological conditions — Anfinsen's dogma. Levinthal's paradox (1969) noted that a random search of conformations would outlast the universe; folding is therefore a guided path, not a lottery. Chaperones help; prions betray; [[machine-learning|machine learning]] (AlphaFold, 2020–21) now predicts many structures from sequence. The concept binds [[dna|DNA]]'s text to [[cell-biology|cell biology]]'s machines, and it is a computational problem as much as a chemical one.`,
    idea: `A polypeptide has a backbone with φ and ψ angles (Ramachandran's map) and side chains that hydrophobically collapse, hydrogen-bond into alpha helices and beta sheets, and sometimes coordinate metals or disulfides. The native state is usually the free-energy minimum, kinetically accessible through folding funnels, a landscape picture due to Bryngelson, Onuchic, Wolynes, and others. Misfolding yields aggregates — amyloid in Alzheimer's, the scrapie form of prion protein that Prusiner named — which can be catalytic in the worst sense. Molecular chaperones (GroEL/GroES, Hsp70) do not add information so much as they prevent off-pathway sticking. Structure determination meant X-ray crystallography, NMR, and now cryo-EM; prediction meant energy functions until neural nets learned the statistics of the Protein Data Bank. The working idea is that function is geometry, and geometry is a compromise among a million weak interactions that [[algorithms|algorithms]] can increasingly guess. Energy landscapes are funnelled for evolved sequences and rugged for random ones, which is why [[evolution|evolution]] is also a search for foldable strings, not only for catalytic ones. Disulfide bonds and proline isomers add kinetic traps that enzymes (PDI, cyclophilins) must unlock.`,
    lineage: `Fischer's lock and key, then Koshland's induced fit, were theories of function before folding was a field. Pauling's helices and sheets, Kendrew's myoglobin, and Perutz's hemoglobin made structure a science. Anfinsen's reductive experiments won a Nobel in 1972. Levinthal posed the kinetic riddle. Women and men in the CASP competition, every two years from 1994, scored prediction as a sport. Baker's Rosetta was the best of the physics-like methods; DeepMind's AlphaFold2, at CASP14, crossed a threshold that felt like a phase change. The Protein Data Bank, founded in 1971, was the unnoticed commons the neural net ate. Ramachandran's plot of allowed angles, from Madras in the 1960s, remains the first picture students see. White and Wimley measured hydrophobicity scales; Dill and Chan drew the funnel. CASP became the field's Olympics, and then, after AlphaFold, a different kind of contest against a machine.`,
    tension: `Sequence determines structure except when it does not: intrinsically disordered proteins, metamorphic folds, post-translational modification, and the cellular crowdedness Anfinsen's dilute tubes omitted. AlphaFold's brilliance is statistical and can hallucinate confidence; experimental structure remains the court of appeal, especially for complexes, membrane proteins, and dynamics. Folding is not static architecture — function is often motion — and prediction of conformational ensembles lags prediction of crystals. Drug design still stumbles where induced fit and entropy dominate. Protein folding cannot yet read a genome into a living cell, because the cell is also lipids, ions, and history. It can, increasingly, read a gene into a ribbon diagram, which is a lot, and not the organism.`,
  },

  microbiome: {
    lede: `The microbiome is the community of microorganisms that live with, on, and in a host — a second genome of sorts, though the metaphor leaks. Human guts carry on the order of as many bacterial cells as human cells, a ratio revised from the famous ten-to-one by Sender, Fuchs, and Milo. Germ-free mice, fecal transplants that cure Clostridioides difficile, and the Human Microbiome Project (launched 2007) made the community a medical object. It neighbors [[ecology|ecology]], [[symbiosis|symbiosis]], the [[immune-system|immune system]], and [[cell-biology|cell biology]], because a mammal is an ecosystem with an identity problem. [[pasteur|Pasteur]] taught us to fear microbes; this concept teaches us to count them as colleagues.`,
    idea: `A microbiome is defined by membership, by genes (the metagenome), and by metabolic jobs: fermenting fiber into short-chain fatty acids, training immunity, synthesizing vitamins, modifying drugs. Composition is personal, plastic with diet and antibiotics, and structured by body site — skin, mouth, vagina, gut are different biomes. Causality is the hard part: many diseases correlate with dysbiosis, few are as clearly caused as C. difficile colitis after ecological collapse. Horizontal gene transfer, including antibiotic-resistance plasmids, makes the community a legal system for DNA. The holobiont idea treats host plus microbes as a unit of [[evolution|evolution]]; critics say it confuses a good ecology with a bad individual. The working idea is that multicellular life never ate alone, and that [[immune-system|immunity]] is as much gardening as war. Metabolites — butyrate, secondary bile acids, trimethylamine-N-oxide — are how a community talks to a liver and a brain. Phage, the viruses of bacteria, may outnumber the bacteria and rewrite which strains win a week, an [[ecology|ecology]] inside the ecology.`,
    lineage: `Leeuwenhoek described animalcules in scrapings of his teeth. Metchnikoff praised yogurt and Bulgarian peasants. Koch's postulates, designed for pathogens, fit commensals poorly. Hungate's anaerobic techniques opened the rumen; Woese's rRNA phylogeny opened a tree in which most of the microbiome had been invisible. Culture-independent 16S sequencing and then shotgun metagenomics, in the 2000s, created the modern field almost at once. Jeff Gordon's gnotobiotic mice linked microbes to adiposity; sequential fecal-transplant trials, and van Nood's 2013 NEJM study, dragged the clinic along. Industrial "probiotic" marketing ran ahead of the trials, a sociological constant. Rosebury's 1962 microorganisms of man, and Savage's 1977 review of colonization resistance, are ancestral texts. The NIH Human Microbiome Project and Europe's MetaHIT turned stools into datasets. Culturomics, in Raoult's group, then tried to bring the uncultured back onto plates.`,
    tension: `Correlation is not colonization with a purpose. Reproducibility across populations is poor; Western, educated cohorts still dominate the databases. The word microbiome itself wobbles between the organisms and their genes. Therapeutic hype — aging, autism, obesity — often exceeds what randomized evidence will carry, with the C. difficile exception as the gold standard that shames its imitators. If the holobiont is the individual, [[philosophy|ethics]] of fecal material, of genetically modified commensals, and of "self" need a rewrite. The microbiome cannot yet be specified as a prescription of species that will take in every host. It can be destroyed in days with a drug, which is both a medical tool and a warning from [[ecology|ecology]].`,
  },

  biodiversity: {
    lede: `Biodiversity is the variety of life at every scale: genes, species, ecosystems, and the interactions that keep them from being a list. E. O. Wilson popularized the word in the 1980s; the 1992 Convention on Biological Diversity made it a legal object. [[linnaeus|Linnaeus]] began the inventory; [[darwin|Darwin]] explained why the inventory has a tree-shape; [[ecology|ecology]] explains why the tree is denser in some places (the tropics, coral reefs, ancient lakes) than in others. The present tense is thinning: a sixth mass extinction, slower than the end-Cretaceous rock but driven by a single species, is the working diagnosis.`,
    idea: `Species richness is the coarsest metric; evenness, phylogenetic diversity, and functional traits catch what richness misses. Latitudinal gradients, species–area curves, and island biogeography (MacArthur and Wilson) are among the few laws-like patterns. Endemism makes some patches irreplaceable: Madagascar, the Cape Floristic Region, the Amazon. Diversity is not only a count of leaves on the tree of [[evolution|evolution]]; it is also the condition for ecological function — pollination, nutrient cycling, productivity — though the shape of that relationship (redundancy versus rivets) is argued. Crop genetic diversity is the agricultural face; language diversity often covaries, a reminder that the thinning is cultural too. The working idea is that variety is both a scientific primitive and a value, and that pretending the two are unrelated is itself a political act. Alpha, beta, and gamma diversity, Whittaker's terms, distinguish local richness from turnover among sites. A rainforest and a kelp forest can share a number and not a structure; conservation that chases the number alone will plant the wrong trees.`,
    lineage: `Naturalists always knew that tropics teem. Humboldt measured it; Wallace drew lines; von Humboldt's Naturgemälde is an early infographic of vertical diversity. The word biodiversity crystallized at a 1986 National Forum, Wilson editing the volume. IUCN Red Lists, Living Planet Indices, and IPBES assessments became the instrumentation. Myers's hotspots directed scarce money; Raven, Wilson, and Ehrlich wrote the alarms. Paleobiology supplied the baseline of five mass extinctions against which the present rate is judged (Raup, Sepkoski, Barnosky). Genomic methods now census microbes and cryptic insects that Linnaean collecting missed, raising the estimated total of species into the millions-to-tens-of-millions fog. Linnaeus inventoried; Humboldt graphed; Wallace drew the line through Indonesia that still bears his name. The Endangered Species Act of 1973, and CITES, turned lists into law. Wilson's Diversity of Life (1992) and the later Half-Earth proposal made the count a political geography.`,
    tension: `What is the unit, and who decides its worth? Species are messy; phylogenetic diversity can recommend saving a tuatara over a hundred beetles; ecosystem services can reduce a forest to a utility, which both funds protection and invites substitution. Northern collections and Southern diversity reproduce colonial extraction in a new key. Climate change moves the pieces faster than reserve boundaries. Biodiversity cannot, by itself, tell a polity whether to value a wetland over a housing estate; it can only make the loss countable and, sometimes, irreversible. The concept's open wound is that the inventory is incomplete, the thinning is faster than the naming, and [[evolution|evolution]] will not restock the same forms on a schedule we will live to see.`,
  },

  symbiosis: {
    lede: `Symbiosis is living together: a long-term intimacy of different species, from lichens to the ancient merger that made mitochondria. Heinrich Anton de Bary defined it in 1879 without requiring that the intimacy be friendly; parasitism, mutualism, and commensalism are tones of the same chord. Lynn Margulis, from 1967, forced [[cell-biology|cell biology]] to admit that eukaryotic cells are stacked endosymbioses. The concept reorganizes [[ecology|ecology]], [[evolution|evolution]], and the [[microbiome|microbiome]] around cooperation as a material fact, not a moral. [[emergence|Emergence]] is nearby: the lichen is not a fungus plus an alga in a bag. It is a third thing.`,
    idea: `When two lineages live in lasting contact, selection begins to act on the pair as well as on the partners. Endosymbiosis is the extreme: an engulfed bacterium becomes an organelle, its genome shrinking as genes move to the nucleus (as in mitochondria from alphaproteobacteria, chloroplasts from cyanobacteria). Lichens, mycorrhizae, corals and their dinoflagellates, ruminants and their anaerobes, and squid with Vibrio fischeri are less extreme and still obligatory in practice. Cheating is the evolutionary weather: rhizobia that take carbon without fixing nitrogen, zooxanthellae that leave a bleached host. Sanctions, partner choice, and vertical transmission are the usual police. The working idea is that the individual of textbook [[biology|biology]] is often a coalition, and that [[natural-selection|natural selection]] invented coalitions as readily as it invented claws. Horizontal gene transfer between partners, and the reduced genomes of Buchnera in aphids, show that intimacy can become irreversible: the guest can no longer live outside, and the host can no longer make the amino acids the guest supplies.`,
    lineage: `Lichens taught the nineteenth century that taxonomy can fail: Schwendener's dual hypothesis was resisted by those who wanted species to be single. De Bary's definition was broad; later textbooks narrowed "symbiosis" to mutualism, a confusion still worth avoiding. Merezhkowsky and Kozo-Polyansky speculated on the symbiotic origin of chloroplasts; Margulis (then Sagan) revived and evidenced the idea against a synthesis that preferred mutation and selection in isolated lineages. Sequencing settled mitochondria and chloroplasts; it left other Margulis claims (spirochetes as undulipodia) unaccepted. The hologenome theory of evolution, and the language of holobionts, is the twenty-first-century intensification, popular and disputed in equal measure. Frank named mycorrhiza in 1885; Buchner catalogued insect endosymbionts in the 1960s. Sagan's 1967 paper, rejected by several journals, became Margulis's Origin of Eukaryotic Cells. The 1998 discovery that mitochondria are nested in the eukaryotic tree as alphaproteobacteria closed the oldest case.`,
    tension: `Is the holobiont a unit of selection or a slightly breathless way to say that hosts have microbes? The debate is not verbal only: it changes what one measures and what one thinks can inherit. Mutualism is not the opposite of [[evolution|evolution]] by conflict; it is conflict temporarily aligned. Human metaphors — partnership, friendship, betrayal — do explanatory harm when they replace payoffs. Organelle origins happened rarely; extrapolating from two or three events to a general law of complexity is tempting and shaky. Symbiosis cannot yet replace the tree of life with a web without remainder: vertical descent still structures most of the macroscopic map. It can, however, stop us from mistaking a coalition for a monad, which is how this atlas prefers to draw living things.`,
  },
};
